218:         private List<ResolvedExpression> flattenLegacyCompositeType(ResolvedExpression composite) {
219:             final TypeInformation<?> resultType =
220:                     fromDataTypeToLegacyInfo(composite.getOutputDataType());
221:             if (!(resultType instanceof CompositeType)) {
222:                 return singletonList(composite);
223:             }
224:             final CompositeType<?> compositeType = (CompositeType<?>) resultType;
225:             return IntStream.range(0, resultType.getArity())
226:                     .mapToObj(
227:                             idx ->
228:                                     resolutionContext
229:                                             .postResolutionFactory()
230:                                             .get(
231:                                                     composite,
232:                                                     valueLiteral(
233:                                                             compositeType.getFieldNames()[idx]),
234:                                                     fromLegacyInfoToDataType(
235:                                                             compositeType.getTypeAt(idx))))
236:                     .collect(Collectors.toList());
237:         }
