250:         private ResolvedExpression runTypeInference(
251:                 String name,
252:                 UnresolvedCallExpression unresolvedCall,
253:                 TypeInference inference,
254:                 List<ResolvedExpression> resolvedArgs,
255:                 @Nullable SurroundingInfo surroundingInfo) {
256: 
257:             final Result inferenceResult =
258:                     TypeInferenceUtil.runTypeInference(
259:                             inference,
260:                             new TableApiCallContext(
261:                                     resolutionContext.typeFactory(),
262:                                     name,
263:                                     unresolvedCall.getFunctionDefinition(),
264:                                     resolvedArgs,
265:                                     resolutionContext.isGroupedAggregation()),
266:                             surroundingInfo);
