298:         /** Validates and cleans an inline, unregistered {@link UserDefinedFunction}. */
299:         private FunctionDefinition prepareInlineUserDefinedFunction(FunctionDefinition functionDef) {
300:             if (functionDef instanceof ScalarFunctionDefinition) {
301:                 final ScalarFunctionDefinition scalarFunctionDef = (ScalarFunctionDefinition) functionDef;
302:                 UserDefinedFunctionHelper.prepareInstance(
303:                         resolutionContext.configuration(), scalarFunctionDef.getScalarFunction());
304:                 return new ScalarFunctionDefinition(scalarFunctionDef.getName(), scalarFunctionDef.getScalarFunction());
305:             } else if (functionDef instanceof TableFunctionDefinition) {
306:                 final TableFunctionDefinition tableFunctionDef = (TableFunctionDefinition) functionDef;
307:                 UserDefinedFunctionHelper.prepareInstance(
308:                         resolutionContext.configuration(), tableFunctionDef.getTableFunction());
309:                 return new TableFunctionDefinition(
310:                         tableFunctionDef.getName(), tableFunctionDef.getTableFunction(), tableFunctionDef.getResultType());
311:             } else if (functionDef instanceof AggregateFunctionDefinition) {
312:                 final AggregateFunctionDefinition aggregateFunctionDef = (AggregateFunctionDefinition) functionDef;
313:                 UserDefinedFunctionHelper.prepareInstance(
314:                         resolutionContext.configuration(), aggregateFunctionDef.getAggregateFunction());
315:                 return new AggregateFunctionDefinition(
316:                         aggregateFunctionDef.getName(),
317:                         aggregateFunctionDef.getAggregateFunction(),
318:                         aggregateFunctionDef.getResultTypeInfo(),
319:                         aggregateFunctionDef.getAccumulatorTypeInfo());
320:             } else if (functionDef instanceof TableAggregateFunctionDefinition) {
321:                 final TableAggregateFunctionDefinition tableAggregateFunctionDef =
322:                         (TableAggregateFunctionDefinition) functionDef;
323:                 UserDefinedFunctionHelper.prepareInstance(
324:                         resolutionContext.configuration(), tableAggregateFunctionDef.getTableAggregateFunction());
325:                 return new TableAggregateFunctionDefinition(
326:                         tableAggregateFunctionDef.getName(),
327:                         tableAggregateFunctionDef.getTableAggregateFunction(),
328:                         tableAggregateFunctionDef.getResultTypeInfo(),
329:                         tableAggregateFunctionDef.getAccumulatorTypeInfo());
330:             } else if (functionDef instanceof UserDefinedFunction) {
331:                 UserDefinedFunctionHelper.prepareInstance(
332:                         resolutionContext.configuration(), (UserDefinedFunction) functionDef);
333:             }
334:             return functionDef;
335:         }
