156:                                     newInference ->
157:                                             runTypeInference(
158:                                                     functionName,
159:                                                     unresolvedCall,
160:                                                     newInference,
161:                                                     resolvedArgs,
162:                                                     surroundingInfo))
163:                             .orElseThrow(
