587:     private ForStOptionsFactory configureOptionsFactory(
588:             @Nullable ForStOptionsFactory originalOptionsFactory,
589:             @Nullable String factoryClassName,
590:             ReadableConfig config,
591:             ClassLoader classLoader)
592:             throws DynamicCodeLoadingException {
593: 
594:         ForStOptionsFactory optionsFactory = null;
595: 
596:         if (originalOptionsFactory != null) {
597:             if (originalOptionsFactory instanceof ConfigurableForStOptionsFactory) {
598:                 originalOptionsFactory =
599:                         ((ConfigurableForStOptionsFactory) originalOptionsFactory)
600:                                 .configure(config);
601:             }
602:             LOG.info("Using application-defined options factory: {}.", originalOptionsFactory);
603: 
604:             optionsFactory = originalOptionsFactory;
605:         } else if (factoryClassName != null) {
606:             try {
607:                 Class<? extends ForStOptionsFactory> clazz =
608:                         Class.forName(factoryClassName, false, classLoader)
609:                                 .asSubclass(ForStOptionsFactory.class);
610: 
611:                 optionsFactory = clazz.newInstance();
612:                 if (optionsFactory instanceof ConfigurableForStOptionsFactory) {
613:                     optionsFactory =
614:                             ((ConfigurableForStOptionsFactory) optionsFactory).configure(config);
615:                 }
616:                 LOG.info("Using configured options factory: {}.", optionsFactory);
617: 
618:             } catch (ClassNotFoundException e) {
619:                 throw new DynamicCodeLoadingException(
620:                         "Cannot find configured options factory class: " + factoryClassName, e);
621:             } catch (ClassCastException | InstantiationException | IllegalAccessException e) {
622:                 throw new DynamicCodeLoadingException(
623:                         "The class configured under '"
624:                                 + ForStOptions.OPTIONS_FACTORY.key()
625:                                 + "' is not a valid options factory ("
626:                                 + factoryClassName
627:                                 + ')',
628:                         e);
629:             }
630:         }
631: 
632:         return optionsFactory;
633:     }
