193:     @Override
194:     protected void registerNamespace(
195:             @Nullable SqlValidatorScope usingScope,
196:             @Nullable String alias,
197:             SqlValidatorNamespace ns,
198:             boolean forceNullable) {
199: 
200:         // Generate a new validator namespace for time travel scenario.
201:         // Since time travel only supports constant expressions, we need to ensure that the period
202:         // of
203:         // snapshot is not an identifier.
204:         Optional<SqlSnapshot> snapshot = getSnapShotNode(ns);
205:         if (usingScope != null
206:                 && snapshot.isPresent()
207:                 && !(hasInputReference(snapshot.get().getPeriod()))) {
208:             SqlSnapshot sqlSnapshot = snapshot.get();
209:             SqlNode periodNode = sqlSnapshot.getPeriod();
210:             SqlToRelConverter sqlToRelConverter = this.createSqlToRelConverter();
211:             RexNode rexNode = sqlToRelConverter.convertExpression(periodNode);
212:             RexNode simplifiedRexNode =
213:                     FlinkRexUtil.simplify(
214:                             sqlToRelConverter.getRexBuilder(),
215:                             rexNode,
216:                             relOptCluster.getPlanner().getExecutor());
217:             List<RexNode> reducedNodes = new ArrayList<>();
218:             relOptCluster
219:                     .getPlanner()
220:                     .getExecutor()
221:                     .reduce(
222:                             relOptCluster.getRexBuilder(),
223:                             Collections.singletonList(simplifiedRexNode),
224:                             reducedNodes);
225:             // check whether period is the unsupported expression
226:             final RexNode reducedNode = reducedNodes.get(0);
227:             if (!(reducedNode instanceof RexLiteral)) {
228:                 throw new ValidationException(
229:                         String.format(
230:                                 "Unsupported time travel expression: %s for the expression can not be reduced to a constant by Flink.",
231:                                 periodNode));
232:             }
233: 
234:             RexLiteral rexLiteral = (RexLiteral) reducedNode;
235:             final RelDataType sqlType = rexLiteral.getType();
236:             if (!SqlTypeUtil.isTimestamp(sqlType)) {
237:                 throw newValidationError(
238:                         periodNode,
239:                         Static.RESOURCE.illegalExpressionForTemporal(
240:                                 sqlType.getSqlTypeName().getName()));
241:             }
242: 
243:             TimestampString timestampString = rexLiteral.getValueAs(TimestampString.class);
244:             checkNotNull(
245:                     timestampString,
246:                     "The time travel expression %s can not reduce to a valid timestamp string. This is a bug. Please file an issue.",
247:                     periodNode);
248: 
249:             TableConfig tableConfig = ShortcutUtils.unwrapContext(relOptCluster).getTableConfig();
250:             ZoneId zoneId = tableConfig.getLocalTimeZone();
251:             long timeTravelTimestamp =
252:                     TimestampData.fromEpochMillis(timestampString.getMillisSinceEpoch())
253:                             .toLocalDateTime()
254:                             .atZone(zoneId)
255:                             .toInstant()
256:                             .toEpochMilli();
257: 
258:             SchemaVersion schemaVersion = TimestampSchemaVersion.of(timeTravelTimestamp);
259:             IdentifierNamespace identifierNamespace = (IdentifierNamespace) ns;
260:             ns =
261:                     new IdentifierSnapshotNamespace(
262:                             identifierNamespace,
263:                             schemaVersion,
264:                             ((DelegatingScope) usingScope).getParent());
265: 
266:             sqlSnapshot.setOperand(
267:                     1,
268:                     SqlLiteral.createTimestamp(
269:                             timestampString,
270:                             rexLiteral.getType().getPrecision(),
271:                             sqlSnapshot.getPeriod().getParserPosition()));
272:         }
273: 
274:         super.registerNamespace(usingScope, alias, ns, forceNullable);
275:     }
