393:                     } else {
394:                         // for TUMBLE(TABLE t3, ...)
395:                         call.setOperand(i, opReplacement);
396:                     }
397:                 }
398:                 // for TUMBLE([DATA =>] SELECT ..., ...)
399:             }
400:         }
