320:     @Override
321:     protected void addToSelectList(
322:             List<SqlNode> list,
323:             Set<String> aliases,
324:             List<Map.Entry<String, RelDataType>> fieldList,
325:             SqlNode exp,
326:             SelectScope scope,
327:             boolean includeSystemVars) {
328:         // Extract column's origin to apply strategy
329:         if (!columnExpansionStrategies.isEmpty() && exp instanceof SqlIdentifier) {
330:             final SqlQualified qualified = scope.fullyQualify((SqlIdentifier) exp);
331:             if (qualified.namespace != null && qualified.namespace.getTable() != null) {
332:                 final CatalogSchemaTable schemaTable =
333:                         (CatalogSchemaTable) qualified.namespace.getTable().table();
334:                 final ResolvedSchema resolvedSchema =
335:                         schemaTable.getContextResolvedTable().getResolvedSchema();
336:                 final String columnName = qualified.suffix().get(0);
337:                 final Column column = resolvedSchema.getColumn(columnName).orElse(null);
338:                 if (qualified.suffix().size() == 1 && column != null) {
339:                     if (includeExpandedColumn(column, columnExpansionStrategies)
340:                             || declaredDescriptorColumn(scope, column)) {
341:                         super.addToSelectList(
342:                                 list, aliases, fieldList, exp, scope, includeSystemVars);
343:                     }
344:                     return;
345:                 }
346:             }
347:         }
348: 
349:         // Always add to list
350:         super.addToSelectList(list, aliases, fieldList, exp, scope, includeSystemVars);
351:     }
352: 
353:     @Override
354:     protected @PolyNull SqlNode performUnconditionalRewrites(
355:             @PolyNull SqlNode node, boolean underFrom) {
356: 
357:         // Special case for window TVFs like:
358:         // TUMBLE(TABLE t, DESCRIPTOR(metadata_virtual), INTERVAL '1' MINUTE))
359:         //
360:         // "TABLE t" is translated into an implicit "SELECT * FROM t". This would ignore columns
361:         // that are not expanded by default. However, the descriptor explicitly states the need
362:         // for this column. Therefore, explicit table expressions (for window TVFs at most one)
363:         // are captured before rewriting and replaced with a "marker" SqlSelect that contains the
364:         // descriptor information. The "marker" SqlSelect is considered during column expansion.
365:         final List<SqlIdentifier> explicitTableArgs = getTableOperands(node);
366: 
367:         final SqlNode rewritten = super.performUnconditionalRewrites(node, underFrom);
368: 
369:         if (!(node instanceof SqlBasicCall)) {
370:             return rewritten;
371:         }
372:         final SqlBasicCall call = (SqlBasicCall) node;
373:         final SqlOperator operator = call.getOperator();
374: 
375:         if (operator instanceof SqlWindowTableFunction) {
376:             if (explicitTableArgs.stream().allMatch(Objects::isNull)) {
377:                 return rewritten;
378:             }
379: 
380:             final List<SqlIdentifier> descriptors =
381:                     call.getOperandList().stream()
382:                             .flatMap(FlinkCalciteSqlValidator::extractDescriptors)
383:                             .collect(Collectors.toList());
384: 
385:             for (int i = 0; i < call.operandCount(); i++) {
386:                 final SqlIdentifier tableArg = explicitTableArgs.get(i);
387:                 if (tableArg != null) {
388:                     final SqlNode opReplacement = new ExplicitTableSqlSelect(tableArg, descriptors);
389:                     if (call.operand(i).getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
390:                         // for TUMBLE(DATA => TABLE t3, ...)
391:                         final SqlCall assignment = call.operand(i);
392:                         assignment.setOperand(0, opReplacement);
393:                     } else {
394:                         // for TUMBLE(TABLE t3, ...)
395:                         call.setOperand(i, opReplacement);
396:                     }
397:                 }
398:                 // for TUMBLE([DATA =>] SELECT ..., ...)
399:             }
400:         }
401: 
402:         return rewritten;
403:     }
404: 
405:     // --------------------------------------------------------------------------------------------
406:     // Column expansion
407:     // --------------------------------------------------------------------------------------------
408: 
409:     /**
410:      * A special {@link SqlSelect} to capture the origin of a {@link SqlKind#EXPLICIT_TABLE} within
411:      * TVF operands.
412:      */
413:     private static class ExplicitTableSqlSelect extends SqlSelect {
414: 
415:         private final List<SqlIdentifier> descriptors;
416: 
417:         public ExplicitTableSqlSelect(SqlIdentifier table, List<SqlIdentifier> descriptors) {
418:             super(
419:                     SqlParserPos.ZERO,
420:                     null,
421:                     SqlNodeList.of(SqlIdentifier.star(SqlParserPos.ZERO)),
422:                     table,
423:                     null,
424:                     null,
425:                     null,
426:                     null,
427:                     null,
428:                     null,
429:                     null,
430:                     null);
431:             this.descriptors = descriptors;
432:         }
433:     }
434: 
435:     /**
436:      * Returns whether the given column has been declared in a {@link SqlKind#DESCRIPTOR} next to a
437:      * {@link SqlKind#EXPLICIT_TABLE} within TVF operands.
438:      */
439:     private static boolean declaredDescriptorColumn(SelectScope scope, Column column) {
440:         if (!(scope.getNode() instanceof ExplicitTableSqlSelect)) {
441:             return false;
442:         }
443:         final ExplicitTableSqlSelect select = (ExplicitTableSqlSelect) scope.getNode();
444:         return select.descriptors.stream()
445:                 .map(SqlIdentifier::getSimple)
446:                 .anyMatch(id -> id.equals(column.getName()));
447:     }
448: 
449:     /**
450:      * Returns all {@link SqlKind#EXPLICIT_TABLE} operands within TVF operands. A list entry is
451:      * {@code null} if the operand is not an {@link SqlKind#EXPLICIT_TABLE}.
452:      */
453:     private static List<SqlIdentifier> getTableOperands(SqlNode node) {
454:         if (!(node instanceof SqlBasicCall)) {
455:             return null;
456:         }
457:         final SqlBasicCall call = (SqlBasicCall) node;
458: 
459:         if (!(call.getOperator() instanceof SqlFunction)) {
460:             return null;
461:         }
462:         final SqlFunction function = (SqlFunction) call.getOperator();
463: 
464:         if (!isTableFunction(function)) {
465:             return null;
466:         }
467: 
468:         return call.getOperandList().stream()
469:                 .map(FlinkCalciteSqlValidator::extractExplicitTable)
470:                 .collect(Collectors.toList());
471:     }
472: 
473:     private static @Nullable SqlIdentifier extractExplicitTable(SqlNode op) {
474:         if (op.getKind() == SqlKind.EXPLICIT_TABLE) {
475:             final SqlBasicCall opCall = (SqlBasicCall) op;
476:             if (opCall.operandCount() == 1 && opCall.operand(0) instanceof SqlIdentifier) {
477:                 // for TUMBLE(TABLE t3, ...)
478:                 return opCall.operand(0);
479:             }
480:         } else if (op.getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
481:             // for TUMBLE(DATA => TABLE t3, ...)
482:             final SqlBasicCall opCall = (SqlBasicCall) op;
483:             return extractExplicitTable(opCall.operand(0));
484:         }
485:         return null;
486:     }
487: 
488:     private static Stream<SqlIdentifier> extractDescriptors(SqlNode op) {
489:         if (op.getKind() == SqlKind.DESCRIPTOR) {
490:             // for TUMBLE(..., DESCRIPTOR(col), ...)
491:             final SqlBasicCall opCall = (SqlBasicCall) op;
492:             return opCall.getOperandList().stream()
493:                     .filter(SqlIdentifier.class::isInstance)
494:                     .map(SqlIdentifier.class::cast);
495:         } else if (op.getKind() == SqlKind.ARGUMENT_ASSIGNMENT) {
496:             // for TUMBLE(..., TIMECOL => DESCRIPTOR(col), ...)
497:             final SqlBasicCall opCall = (SqlBasicCall) op;
498:             return extractDescriptors(opCall.operand(0));
499:         }
500:         return Stream.empty();
501:     }
502: 
503:     private static boolean isTableFunction(SqlFunction function) {
504:         return function instanceof SqlTableFunction
505:                 || function.getFunctionType() == SqlFunctionCategory.USER_DEFINED_TABLE_FUNCTION;
506:     }
507: }
