1321:     private CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1322:             createExecutionGraphWithAvailableResourcesAsync(
1323:                     @Nullable ExecutionGraph previousExecutionGraph) {
1324:         final JobSchedulingPlan schedulingPlan;
1325:         final VertexParallelismStore adjustedParallelismStore;
1326: 
1327:         try {
1328:             schedulingPlan = determineParallelism(slotAllocator, previousExecutionGraph);
1329:             JobGraph adjustedJobGraph = jobInformation.copyJobGraph();
1330: 
1331:             for (JobVertex vertex : adjustedJobGraph.getVertices()) {
1332:                 JobVertexID id = vertex.getID();
1333: 
1334:                 // use the determined "available parallelism" to use
1335:                 // the resources we have access to
1336:                 vertex.setParallelism(schedulingPlan.getVertexParallelism().getParallelism(id));
1337:             }
1338: 
1339:             // use the originally configured max parallelism
1340:             // as the default for consistent runs
1341:             adjustedParallelismStore =
1342:                     computeVertexParallelismStoreForExecution(
1343:                             adjustedJobGraph,
1344:                             settings.getExecutionMode(),
1345:                             (vertex) -> {
1346:                                 VertexParallelismInformation vertexParallelismInfo =
1347:                                         initialParallelismStore.getParallelismInfo(vertex.getID());
1348:                                 return vertexParallelismInfo.getMaxParallelism();
1349:                             });
1350:         } catch (Exception exception) {
1351:             return FutureUtils.completedExceptionally(exception);
1352:         }
1353: 
1354:         return createExecutionGraphAndRestoreStateAsync(adjustedParallelismStore)
1355:                 .thenApply(
1356:                         executionGraph ->
1357:                                 CreatingExecutionGraph.ExecutionGraphWithVertexParallelism.create(
1358:                                         executionGraph, schedulingPlan));
1359:     }
