567:     private static void assertPreconditions(JobGraph jobGraph) throws RuntimeException {
568:         Preconditions.checkState(
569:                 jobGraph.getJobType() == JobType.STREAMING,
570:                 "The adaptive scheduler only supports streaming jobs.");
571: 
572:         for (JobVertex vertex : jobGraph.getVertices()) {
573:             Preconditions.checkState(
574:                     vertex.getParallelism() > 0,
575:                     "The adaptive scheduler expects the parallelism being set for each JobVertex (violated JobVertex: %s).",
576:                     vertex.getID());
577:             for (JobEdge jobEdge : vertex.getInputs()) {
578:                 Preconditions.checkState(
579:                         jobEdge.getSource()
580:                                 .getResultType()
581:                                 .isPipelinedOrPipelinedBoundedResultPartition(),
582:                         "The adaptive scheduler supports pipelined data exchanges (violated by %s -> %s).",
583:                         jobEdge.getSource().getProducer(),
584:                         jobEdge.getTarget().getID());
585:             }
586:         }
587:     }
