97:     /**
98:      * The number of expected memory segments of this buffer pool.
99:      *
100:      * <p>Usually, the buffers in {@link NetworkBufferPool} do not exactly meet the expectations of
101:      * all {@link LocalBufferPool}s, so typically this value is used as a weight to allocate buffers
102:      * to each {@link LocalBufferPool}.
103:      */
104:     private final int requiredNumberOfMemorySegments;
105: 
106:     /** The number of guaranteed (minimum number of) memory segments of this buffer pool. */
107:     private final int minNumberOfMemorySegments;
108: 
109:     /** Maximum number of network buffers to allocate. */
110:     private final int maxNumberOfMemorySegments;
111: 
112:     /** The current size of this pool. */
113:     @GuardedBy("availableMemorySegments")
114:     private int currentPoolSize;
115: 
116:     /**
117:      * Number of all memory segments, which have been requested from the network buffer pool and are
118:      * somehow referenced through this pool (e.g. wrapped in Buffer instances or as available
119:      * segments).
120:      */
121:     @GuardedBy("availableMemorySegments")
122:     private int numberOfRequestedMemorySegments;
123: 
124:     private final int maxBuffersPerChannel;
125: 
126:     @GuardedBy("availableMemorySegments")
127:     private final int[] subpartitionBuffersCount;
128: 
129:     private final BufferRecycler[] subpartitionBufferRecyclers;
130: 
131:     @GuardedBy("availableMemorySegments")
132:     private int unavailableSubpartitionsCount = 0;
133: 
134:     private int maxOverdraftBuffersPerGate;
135: 
136:     @GuardedBy("availableMemorySegments")
137:     private boolean isDestroyed;
138: 
139:     @GuardedBy("availableMemorySegments")
140:     private final AvailabilityHelper availabilityHelper = new AvailabilityHelper();
