143:      * Indicates whether this {@link LocalBufferPool} has requested to be notified on the next time
144:      * that global pool becoming available, so it can then request buffer from the global pool.
145:      */
146:     @GuardedBy("availableMemorySegments")
147:     private boolean requestingNotificationOfGlobalPoolAvailable;
