189:     /**
190:      * Local buffer pool based on the given <tt>networkBufferPool</tt> and <tt>bufferPoolOwner</tt>
191:      * with a minimal and maximal number of network buffers being available.
192:      *
193:      * @param networkBufferPool global network buffer pool to get buffers from
194:      * @param requiredNumberOfMemorySegments required number of network buffers
195:      * @param minNumberOfMemorySegments minimum number of network buffers
196:      * @param maxNumberOfMemorySegments maximum number of network buffers to allocate
197:      * @param numberOfSubpartitions number of subpartitions
198:      * @param maxBuffersPerChannel maximum number of buffers to use for each channel
199:      * @param maxOverdraftBuffersPerGate maximum number of overdraft buffers to use for each gate
200:      */
201:     LocalBufferPool(
202:             NetworkBufferPool networkBufferPool,
203:             int requiredNumberOfMemorySegments,
204:             int minNumberOfMemorySegments,
205:             int maxNumberOfMemorySegments,
206:             int numberOfSubpartitions,
207:             int maxBuffersPerChannel,
208:             int maxOverdraftBuffersPerGate) {
209:         checkArgument(
210:                 minNumberOfMemorySegments > 0,
211:                 "Minimum number of memory segments (%s) should be larger than 0.",
212:                 minNumberOfMemorySegments);
213: 
214:         checkArgument(
215:                 requiredNumberOfMemorySegments >= minNumberOfMemorySegments,
216:                 "Minimum number of memory segments (%s) should not be larger than expected (%s).",
217:                 minNumberOfMemorySegments,
218:                 requiredNumberOfMemorySegments);
219: 
220:         checkArgument(
221:                 maxNumberOfMemorySegments >= requiredNumberOfMemorySegments,
222:                 "Maximum number of memory segments (%s) should not be smaller than expected (%s).",
223:                 maxNumberOfMemorySegments,
224:                 requiredNumberOfMemorySegments);
225: 
226:         LOG.debug(
227:                 "Using a local buffer pool who has the minimum-expected-maximum number of buffers as {}-{}-{}.",
228:                 minNumberOfMemorySegments,
229:                 requiredNumberOfMemorySegments,
230:                 maxNumberOfMemorySegments);
231: 
232:         this.networkBufferPool = networkBufferPool;
233:         this.requiredNumberOfMemorySegments = requiredNumberOfMemorySegments;
234:         this.currentPoolSize = minNumberOfMemorySegments;
235:         this.minNumberOfMemorySegments = minNumberOfMemorySegments;
236:         this.maxNumberOfMemorySegments = maxNumberOfMemorySegments;
237: 
238:         if (numberOfSubpartitions > 0) {
239:             checkArgument(
240:                     maxBuffersPerChannel > 0,
241:                     "Maximum number of buffers for each channel (%s) should be larger than 0.",
242:                     maxBuffersPerChannel);
243:             checkArgument(
244:                     maxOverdraftBuffersPerGate >= 0,
245:                     "Maximum number of overdraft buffers for each gate (%s) should not be less than 0.",
246:                     maxOverdraftBuffersPerGate);
247:         }
248: 
249:         this.subpartitionBuffersCount = new int[numberOfSubpartitions];
250:         subpartitionBufferRecyclers = new BufferRecycler[numberOfSubpartitions];
251:         for (int i = 0; i < subpartitionBufferRecyclers.length; i++) {
252:             subpartitionBufferRecyclers[i] = new SubpartitionBufferRecycler(i, this);
253:         }
254:         this.maxBuffersPerChannel = maxBuffersPerChannel;
255:         this.maxOverdraftBuffersPerGate = maxOverdraftBuffersPerGate;
256: 
257:         // Lock is only taken, because #checkAndUpdateAvailability asserts it. It's a small penalty
258:         // for thread safety.
259:         synchronized (this.availableMemorySegments) {
260:             checkAndUpdateAvailability();
261:         }
262:     }
