209:                 numberOfSegmentsToRequest >= 0,
210:                 "Number of buffers to request must be non-negative.");
211: 
212:         synchronized (factoryLock) {
213:             if (isDestroyed) {
214:                 throw new IllegalStateException("Network buffer pool has already been destroyed.");
215:             }
