99:     @VisibleForTesting
100:     public NetworkBufferPool(int numberOfSegmentsToAllocate, int segmentSize) {
101:         this(numberOfSegmentsToAllocate, segmentSize, Duration.ofMillis(Integer.MAX_VALUE));
102:     }
103: 
104:     /** Allocates all {@link MemorySegment} instances managed by this pool. */
105:     public NetworkBufferPool(
106:             int numberOfSegmentsToAllocate, int segmentSize, Duration requestSegmentsTimeout) {
107:         this.totalNumberOfMemorySegments = numberOfSegmentsToAllocate;
108:         this.memorySegmentSize = segmentSize;
109: 
110:         Preconditions.checkNotNull(requestSegmentsTimeout);
111:         checkArgument(
112:                 requestSegmentsTimeout.toMillis() > 0,
113:                 "The timeout for requesting exclusive buffers should be positive.");
114:         this.requestSegmentsTimeout = requestSegmentsTimeout;
115: 
116:         final long sizeInLong = (long) segmentSize;
117: 
118:         try {
119:             this.availableMemorySegments = new ArrayDeque<>(numberOfSegmentsToAllocate);
120:         } catch (OutOfMemoryError err) {
121:             throw new OutOfMemoryError(
122:                     "Could not allocate buffer queue of length "
123:                             + numberOfSegmentsToAllocate
124:                             + " - "
125:                             + err.getMessage());
126:         }
127: 
128:         try {
129:             for (int i = 0; i < numberOfSegmentsToAllocate; i++) {
130:                 availableMemorySegments.add(
131:                         MemorySegmentFactory.allocateUnpooledOffHeapMemory(segmentSize, null));
132:             }
133:         } catch (OutOfMemoryError err) {
134:             int allocated = availableMemorySegments.size();
135: 
136:             // free some memory
137:             availableMemorySegments.clear();
138: 
139:             long requiredMb = (sizeInLong * numberOfSegmentsToAllocate) >> 20;
140:             long allocatedMb = (sizeInLong * allocated) >> 20;
141:             long missingMb = requiredMb - allocatedMb;
142: 
143:             throw new OutOfMemoryError(
144:                     "Could not allocate enough memory segments for NetworkBufferPool "
145:                             + "(required (MB): "
146:                             + requiredMb
147:                             + ", allocated (MB): "
148:                             + allocatedMb
149:                             + ", missing (MB): "
150:                             + missingMb
151:                             + "). Cause: "
152:                             + err.getMessage());
153:         }
154: 
155:         availabilityHelper.resetAvailable();
156: 
157:         long allocatedMb = (sizeInLong * availableMemorySegments.size()) >> 20;
158: 
159:         LOG.info(
160:                 "Allocated {} MB for network buffer pool (number of memory segments: {}, bytes per segment: {}).",
161:                 allocatedMb,
162:                 availableMemorySegments.size(),
163:                 segmentSize);
164:     }
