56: /**
57:  * The NetworkBufferPool is a fixed size pool of {@link MemorySegment} instances for the network
58:  * stack.
59:  *
60:  * <p>The NetworkBufferPool creates {@link LocalBufferPool}s from which the individual tasks draw
61:  * the buffers for the network data transfer. When new local buffer pools are created, the
62:  * NetworkBufferPool dynamically redistributes the buffers between the pools. The redistribution
63:  * logic is to make the number of buffers of each buffer pool fall within the minimum and maximum
64:  * numbers while endeavoring to closely align with its individual required number.
65:  */
66: public class NetworkBufferPool
67:         implements BufferPoolFactory, MemorySegmentProvider, AvailabilityProvider {
68: 
69:     public static final int UNBOUNDED_POOL_SIZE = Integer.MAX_VALUE;
70: 
71:     private static final int USAGE_WARNING_THRESHOLD = 100;
72: 
73:     private static final Logger LOG = LoggerFactory.getLogger(NetworkBufferPool.class);
74: 
75:     private final int totalNumberOfMemorySegments;
76: 
77:     private final int memorySegmentSize;
78: 
79:     private final ArrayDeque<MemorySegment> availableMemorySegments;
80: 
81:     private volatile boolean isDestroyed;
82: 
83:     // ---- Managed buffer pools ----------------------------------------------
84: 
85:     private final Object factoryLock = new Object();
86: 
87:     private final Set<LocalBufferPool> allBufferPools = new HashSet<>();
88: 
89:     private final Set<LocalBufferPool> resizableBufferPools = new HashSet<>();
90: 
91:     private int numTotalRequiredBuffers;
92: 
93:     private final Duration requestSegmentsTimeout;
94: 
95:     private final AvailabilityHelper availabilityHelper = new AvailabilityHelper();
96: 
97:     private int lastCheckedUsage = -1;
98: 
99:     @VisibleForTesting
100:     public NetworkBufferPool(int numberOfSegmentsToAllocate, int segmentSize) {
101:         this(numberOfSegmentsToAllocate, segmentSize, Duration.ofMillis(Integer.MAX_VALUE));
102:     }
103: 
104:     /** Allocates all {@link MemorySegment} instances managed by this pool. */
105:     public NetworkBufferPool(
106:             int numberOfSegmentsToAllocate, int segmentSize, Duration requestSegmentsTimeout) {
107:         this.totalNumberOfMemorySegments = numberOfSegmentsToAllocate;
108:         this.memorySegmentSize = segmentSize;
109: 
110:         Preconditions.checkNotNull(requestSegmentsTimeout);
111:         checkArgument(
112:                 requestSegmentsTimeout.toMillis() > 0,
113:                 "The timeout for requesting exclusive buffers should be positive.");
114:         this.requestSegmentsTimeout = requestSegmentsTimeout;
115: 
116:         final long sizeInLong = (long) segmentSize;
117: 
118:         try {
119:             this.availableMemorySegments = new ArrayDeque<>(numberOfSegmentsToAllocate);
120:         } catch (OutOfMemoryError err) {
121:             throw new OutOfMemoryError(
122:                     "Could not allocate buffer queue of length "
123:                             + numberOfSegmentsToAllocate
124:                             + " - "
125:                             + err.getMessage());
126:         }
127: 
128:         try {
129:             for (int i = 0; i < numberOfSegmentsToAllocate; i++) {
130:                 availableMemorySegments.add(
131:                         MemorySegmentFactory.allocateUnpooledOffHeapMemory(segmentSize, null));
132:             }
133:         } catch (OutOfMemoryError err) {
134:             int allocated = availableMemorySegments.size();
135: 
136:             // free some memory
137:             availableMemorySegments.clear();
138: 
139:             long requiredMb = (sizeInLong * numberOfSegmentsToAllocate) >> 20;
140:             long allocatedMb = (sizeInLong * allocated) >> 20;
141:             long missingMb = requiredMb - allocatedMb;
142: 
143:             throw new OutOfMemoryError(
144:                     "Could not allocate enough memory segments for NetworkBufferPool "
145:                             + "(required (MB): "
146:                             + requiredMb
147:                             + ", allocated (MB): "
148:                             + allocatedMb
149:                             + ", missing (MB): "
150:                             + missingMb
151:                             + "). Cause: "
152:                             + err.getMessage());
153:         }
154: 
155:         availabilityHelper.resetAvailable();
156: 
157:         long allocatedMb = (sizeInLong * availableMemorySegments.size()) >> 20;
158: 
159:         LOG.info(
160:                 "Allocated {} MB for network buffer pool (number of memory segments: {}, bytes per segment: {}).",
161:                 allocatedMb,
162:                 availableMemorySegments.size(),
163:                 segmentSize);
164:     }
165: 
166:     /**
167:      * Different from {@link #requestUnpooledMemorySegments} for unpooled segments allocation. This
168:      * method and the below {@link #requestPooledMemorySegmentsBlocking} method are designed to be
169:      * used from {@link LocalBufferPool} for pooled memory segments allocation. Note that these
170:      * methods for pooled memory segments requesting and recycling are prohibited from acquiring the
171:      * factoryLock to avoid deadlock.
172:      */
173:     @Nullable
174:     public MemorySegment requestPooledMemorySegment() {
175:         synchronized (availableMemorySegments) {
176:             return internalRequestMemorySegment();
177:         }
178:     }
179: 
180:     public List<MemorySegment> requestPooledMemorySegmentsBlocking(int numberOfSegmentsToRequest)
181:             throws IOException {
182:         return internalRequestMemorySegments(numberOfSegmentsToRequest);
183:     }
184: 
185:     /**
186:      * Corresponding to {@link #requestPooledMemorySegmentsBlocking} and {@link
187:      * #requestPooledMemorySegment}, this method is for pooled memory segments recycling.
188:      */
189:     public void recyclePooledMemorySegment(MemorySegment segment) {
190:         // Adds the segment back to the queue, which does not immediately free the memory
191:         // however, since this happens when references to the global pool are also released,
192:         // making the availableMemorySegments queue and its contained object reclaimable
193:         internalRecycleMemorySegments(Collections.singleton(checkNotNull(segment)));
194:     }
195: 
196:     /**
197:      * Unpooled memory segments are requested directly from {@link NetworkBufferPool}, as opposed to
198:      * pooled segments, that are requested through {@link BufferPool} that was created from this
199:      * {@link NetworkBufferPool} (see {@link #createBufferPool}). They are used for example for
200:      * exclusive {@link RemoteInputChannel} credits, that are permanently assigned to that channel,
201:      * and never returned to any {@link BufferPool}. As opposed to pooled segments, when requested,
202:      * unpooled segments needs to be accounted against {@link #numTotalRequiredBuffers}, which might
203:      * require redistribution of the segments.
204:      */
205:     @Override
206:     public List<MemorySegment> requestUnpooledMemorySegments(int numberOfSegmentsToRequest)
207:             throws IOException {
208:         checkArgument(
209:                 numberOfSegmentsToRequest >= 0,
210:                 "Number of buffers to request must be non-negative.");
211: 
212:         synchronized (factoryLock) {
213:             if (isDestroyed) {
214:                 throw new IllegalStateException("Network buffer pool has already been destroyed.");
215:             }
216: 
217:             if (numberOfSegmentsToRequest == 0) {
218:                 return Collections.emptyList();
219:             }
220: 
221:             tryRedistributeBuffers(numberOfSegmentsToRequest);
222:         }
223: 
224:         try {
225:             return internalRequestMemorySegments(numberOfSegmentsToRequest);
226:         } catch (IOException exception) {
227:             revertRequiredBuffers(numberOfSegmentsToRequest);
228:             ExceptionUtils.rethrowIOException(exception);
229:             return null;
230:         }
231:     }
232: 
233:     private List<MemorySegment> internalRequestMemorySegments(int numberOfSegmentsToRequest)
234:             throws IOException {
235:         final List<MemorySegment> segments = new ArrayList<>(numberOfSegmentsToRequest);
236:         try {
237:             final Deadline deadline = Deadline.fromNow(requestSegmentsTimeout);
238:             while (true) {
239:                 if (isDestroyed) {
240:                     throw new IllegalStateException("Buffer pool is destroyed.");
241:                 }
242: 
243:                 MemorySegment segment;
244:                 synchronized (availableMemorySegments) {
245:                     if ((segment = internalRequestMemorySegment()) == null) {
246:                         availableMemorySegments.wait(2000);
247:                     }
248:                 }
249:                 if (segment != null) {
250:                     segments.add(segment);
251:                 }
252: 
253:                 if (segments.size() >= numberOfSegmentsToRequest) {
254:                     break;
255:                 }
256: 
257:                 if (!deadline.hasTimeLeft()) {
258:                     throw new IOException(
259:                             String.format(
260:                                     "Timeout triggered when requesting exclusive buffers: %s, "
261:                                             + " or you may increase the timeout which is %dms by setting the key '%s'.",
262:                                     getConfigDescription(),
263:                                     requestSegmentsTimeout.toMillis(),
264:                                     NettyShuffleEnvironmentOptions.NETWORK_BUFFERS_REQUEST_TIMEOUT
265:                                             .key()));
266:                 }
267:             }
268:         } catch (Throwable e) {
269:             internalRecycleMemorySegments(segments);
270:             ExceptionUtils.rethrowIOException(e);
271:         }
272: 
273:         return segments;
274:     }
275: 
276:     @Nullable
277:     private MemorySegment internalRequestMemorySegment() {
278:         assert Thread.holdsLock(availableMemorySegments);
279: 
280:         final MemorySegment segment = availableMemorySegments.poll();
281:         if (availableMemorySegments.isEmpty() && segment != null) {
282:             availabilityHelper.resetUnavailable();
283:         }
284:         return segment;
285:     }
286: 
287:     /**
288:      * Corresponding to {@link #requestUnpooledMemorySegments}, this method is for unpooled memory
289:      * segments recycling.
290:      */
291:     @Override
292:     public void recycleUnpooledMemorySegments(Collection<MemorySegment> segments) {
293:         internalRecycleMemorySegments(segments);
294:         revertRequiredBuffers(segments.size());
295:     }
296: 
297:     private void revertRequiredBuffers(int size) {
298:         synchronized (factoryLock) {
299:             numTotalRequiredBuffers -= size;
300: 
301:             // note: if this fails, we're fine for the buffer pool since we already recycled the
302:             // segments
303:             redistributeBuffers();
304:         }
305:     }
306: 
307:     private void internalRecycleMemorySegments(Collection<MemorySegment> segments) {
308:         CompletableFuture<?> toNotify = null;
309:         synchronized (availableMemorySegments) {
310:             if (availableMemorySegments.isEmpty() && !segments.isEmpty()) {
311:                 toNotify = availabilityHelper.getUnavailableToResetAvailable();
312:             }
313:             availableMemorySegments.addAll(segments);
314:             availableMemorySegments.notifyAll();
315:         }
316: 
317:         if (toNotify != null) {
318:             toNotify.complete(null);
319:         }
320:     }
321: 
322:     public void destroy() {
323:         synchronized (factoryLock) {
324:             isDestroyed = true;
325:         }
326: 
327:         synchronized (availableMemorySegments) {
328:             MemorySegment segment;
329:             while ((segment = availableMemorySegments.poll()) != null) {
330:                 segment.free();
331:             }
332:         }
333:     }
