1236:     private long getCheckpointIntervalConfig(RestClusterClient<?> restClusterClient, String jobId)
1237:             throws Exception {
1238:         CheckpointConfigInfo checkpointConfigInfo =
1239:                 sendJobRequest(
1240:                         restClusterClient,
1241:                         CheckpointConfigHeaders.getInstance(),
1242:                         EmptyRequestBody.getInstance(),
1243:                         jobId);
1244:         return RestMapperUtils.getStrictObjectMapper()
1245:                 .readTree(
1246:                         RestMapperUtils.getStrictObjectMapper()
1247:                                 .writeValueAsString(checkpointConfigInfo))
1248:                 .get("interval")
1249:                 .asLong();
