324:     @Test
325:     void testAlterMaterializedTableRefreshInContinuousMode() throws Exception {
326:         long timeout = Duration.ofSeconds(20).toMillis();
327:         long pause = Duration.ofSeconds(2).toMillis();
328: 
329:         List<Row> data = new ArrayList<>();
330:         data.add(Row.of(1L, 1L, 1L, "2024-01-01"));
331:         data.add(Row.of(2L, 2L, 2L, "2024-01-02"));
332:         data.add(Row.of(3L, 3L, 3L, "2024-01-02"));
333: 
334:         createAndVerifyCreateMaterializedTableWithData(
335:                 "my_materialized_table",
336:                 data,
337:                 Collections.singletonMap("ds", "yyyy-MM-dd"),
338:                 RefreshMode.CONTINUOUS);
339: 
340:         // remove the last element
341:         data.remove(2);
342: 
343:         long currentTime = System.currentTimeMillis();
344:         String alterStatement =
345:                 "ALTER MATERIALIZED TABLE my_materialized_table REFRESH PARTITION (ds = '2024-01-02')";
346:         OperationHandle alterHandle =
347:                 service.executeStatement(sessionHandle, alterStatement, -1, new Configuration());
348:         awaitOperationTermination(service, sessionHandle, alterHandle);
349:         List<RowData> result = fetchAllResults(service, sessionHandle, alterHandle);
350:         assertThat(result.size()).isEqualTo(1);
351:         String jobId = result.get(0).getString(0).toString();
352: 
353:         // 1. verify a new job is created
354:         verifyRefreshJobCreated(restClusterClient, jobId, currentTime);
355: 
356:         // 2. verify the new job overwrite the data
357:         CommonTestUtils.waitUtil(
358:                 () ->
359:                         fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table").size()
360:                                 == data.size(),
361:                 Duration.ofMillis(timeout),
362:                 Duration.ofMillis(pause),
363:                 "Failed to verify the data in materialized table.");
364:         assertThat(
365:                         fetchTableData(
366:                                         sessionHandle,
367:                                         "SELECT * FROM my_materialized_table where ds = '2024-01-02'")
368:                                 .size())
369:                 .isEqualTo(1);
370:     }
