1253:             RestClusterClient<?> restClusterClient, String jobId) throws Exception {
1254:         CheckpointingStatistics checkpointingStatistics =
1255:                 sendJobRequest(
1256:                         restClusterClient,
1257:                         CheckpointingStatisticsHeaders.getInstance(),
