1268:     private static <M extends JobMessageParameters, R extends RequestBody, P extends ResponseBody>
1269:             P sendJobRequest(
1270:                     RestClusterClient<?> restClusterClient,
1271:                     MessageHeaders<R, P, M> headers,
1272:                     R requestBody,
1273:                     String jobId)
1274:                     throws Exception {
1275:         M jobMessageParameters = headers.getUnresolvedMessageParameters();
1276:         jobMessageParameters.jobPathParameter.resolve(JobID.fromHexString(jobId));
1277: 
1278:         return restClusterClient
1279:                 .sendRequest(headers, jobMessageParameters, requestBody)
1280:                 .get(5, TimeUnit.SECONDS);
1281:     }
