352: 
353:         // 1. verify a new job is created
354:         verifyRefreshJobCreated(restClusterClient, jobId, currentTime);
355: 
356:         // 2. verify the new job overwrite the data
357:         CommonTestUtils.waitUtil(
358:                 () ->
359:                         fetchTableData(sessionHandle, "SELECT * FROM my_materialized_table").size()
360:                                 == data.size(),
361:                 Duration.ofMillis(timeout),
362:                 Duration.ofMillis(pause),
363:                 "Failed to verify the data in materialized table.");
364:         assertThat(
365:                         fetchTableData(
366:                                         sessionHandle,
367:                                         "SELECT * FROM my_materialized_table where ds = '2024-01-02'")
368:                                 .size())
369:                 .isEqualTo(1);
370:     }
