416:     public static ArchivedExecutionGraph createSparseArchivedExecutionGraphWithJobVertices(
417:             JobID jobId,
418:             String jobName,
419:             JobStatus jobStatus,
420:             JobType jobType,
421:             @Nullable Throwable throwable,
422:             @Nullable JobCheckpointingSettings checkpointingSettings,
423:             long initializationTimestamp,
424:             Iterable<JobVertex> jobVertices,
425:             VertexParallelismStore initialParallelismStore) {
426:         final Map<JobVertexID, ArchivedExecutionJobVertex> archivedJobVertices = new HashMap<>();
427:         final List<ArchivedExecutionJobVertex> archivedVerticesInCreationOrder = new ArrayList<>();
428:         for (JobVertex jobVertex : jobVertices) {
429:             final VertexParallelismInformation parallelismInfo =
430:                     initialParallelismStore.getParallelismInfo(jobVertex.getID());
431: 
432:             ArchivedExecutionJobVertex archivedJobVertex =
433:                     new ArchivedExecutionJobVertex(
434:                             new ArchivedExecutionVertex[0],
435:                             jobVertex.getID(),
436:                             jobVertex.getName(),
437:                             parallelismInfo.getParallelism(),
438:                             parallelismInfo.getMaxParallelism(),
439:                             jobVertex.getSlotSharingGroup(),
440:                             ResourceProfile.fromResourceSpec(
441:                                     jobVertex.getMinResources(), MemorySize.ZERO),
442:                             new StringifiedAccumulatorResult[0]);
443:             archivedVerticesInCreationOrder.add(archivedJobVertex);
444:             archivedJobVertices.put(archivedJobVertex.getJobVertexId(), archivedJobVertex);
445:         }
446:         return createSparseArchivedExecutionGraph(
447:                 jobId,
448:                 jobName,
449:                 jobStatus,
450:                 jobType,
451:                 archivedJobVertices,
452:                 archivedVerticesInCreationOrder,
453:                 throwable,
454:                 checkpointingSettings,
455:                 initializationTimestamp);
456:     }
