458:     private static ArchivedExecutionGraph createSparseArchivedExecutionGraph(
459:             JobID jobId,
460:             String jobName,
461:             JobStatus jobStatus,
462:             JobType jobType,
463:             Map<JobVertexID, ArchivedExecutionJobVertex> archivedTasks,
464:             List<ArchivedExecutionJobVertex> archivedVerticesInCreationOrder,
465:             @Nullable Throwable throwable,
466:             @Nullable JobCheckpointingSettings checkpointingSettings,
467:             long initializationTimestamp) {
468:         final Map<String, SerializedValue<OptionalFailure<Object>>> serializedUserAccumulators =
469:                 Collections.emptyMap();
470:         StringifiedAccumulatorResult[] archivedUserAccumulators =
471:                 new StringifiedAccumulatorResult[] {};
472: 
473:         final long[] timestamps = new long[JobStatus.values().length];
474:         timestamps[JobStatus.INITIALIZING.ordinal()] = initializationTimestamp;
475: 
476:         String jsonPlan = "{}";
477: 
478:         ErrorInfo failureInfo = null;
479:         if (throwable != null) {
480:             Preconditions.checkState(
481:                     jobStatus == JobStatus.FAILED || jobStatus == JobStatus.SUSPENDED);
482:             long failureTime = System.currentTimeMillis();
483:             failureInfo = new ErrorInfo(throwable, failureTime);
484:             timestamps[jobStatus.ordinal()] = failureTime;
485:         }
486: 
487:         return new ArchivedExecutionGraph(
488:                 jobId,
489:                 jobName,
490:                 archivedTasks,
491:                 archivedVerticesInCreationOrder,
492:                 timestamps,
493:                 jobStatus,
494:                 jobType,
495:                 failureInfo,
496:                 jsonPlan,
497:                 archivedUserAccumulators,
498:                 serializedUserAccumulators,
499:                 new ExecutionConfig().archive(),
500:                 false,
501:                 checkpointingSettings == null
502:                         ? null
503:                         : checkpointingSettings.getCheckpointCoordinatorConfiguration(),
504:                 checkpointingSettings == null ? null : CheckpointStatsSnapshot.empty(),
505:                 checkpointingSettings == null ? null : "Unknown",
506:                 checkpointingSettings == null ? null : "Unknown",
507:                 checkpointingSettings == null
508:                         ? TernaryBoolean.UNDEFINED
509:                         : checkpointingSettings.isChangelogStateBackendEnabled(),
510:                 checkpointingSettings == null ? null : "Unknown",
511:                 null,
512:                 0);
513:     }
514: }
