32: /** Describes a relational operation that was created from applying a {@link TableFunction}. */
33: @Internal
34: public class LateralTableQueryOperation implements QueryOperation {
35: 
36:     public static final String LATERAL_TABLE_ALIAS = "$$T_LAT";
37: 
38:     private final ContextResolvedFunction resolvedFunction;
39:     private final List<ResolvedExpression> arguments;
40:     private final ResolvedSchema resolvedSchema;
41: 
42:     public LateralTableQueryOperation(
43:             ContextResolvedFunction resolvedFunction,
44:             List<ResolvedExpression> arguments,
45:             ResolvedSchema resolvedSchema) {
46:         this.resolvedFunction = resolvedFunction;
47:         this.arguments = arguments;
48:         this.resolvedSchema = resolvedSchema;
49:     }
50: 
