52:         return resolvedFunction;
53:     }
54: 
55:     public List<ResolvedExpression> getArguments() {
56:         return arguments;
57:     }
58: 
59:     @Override
60:     public ResolvedSchema getResolvedSchema() {
61:         return resolvedSchema;
62:     }
63: 
64:     @Override
65:     public String asSummaryString() {
66:         Map<String, Object> args = new LinkedHashMap<>();
67:         args.put("function", resolvedFunction);
68:         args.put("arguments", arguments);
69: 
70:         return OperationUtils.formatWithChildren(
71:                 "CalculatedTable", args, getChildren(), Operation::asSummaryString);
72:     }
73: 
74:     @Override
75:     public String asSerializableString() {
76:         // if we ever add multi-way join in JoinQueryOperation we need to sort out uniqueness of the
