80:                 resolvedFunction
81:                         .toCallExpression(arguments, resolvedSchema.toPhysicalRowDataType())
82:                         .asSerializableString(),
83:                 LATERAL_TABLE_ALIAS,
84:                 OperationUtils.formatSelectColumns(resolvedSchema, null));
85:     }
