87:     @Override
88:     public List<QueryOperation> getChildren() {
89:         return Collections.emptyList();
90:     }
91: 
92:     @Override
93:     public <U> U accept(QueryOperationVisitor<U> visitor) {
94:         return visitor.visit(this);
95:     }
