204:     @Override
205:     public void serializeOutputStateHandle(
206:             OutputStateHandle handle, DataOutputStream dos) throws IOException {
207:         channelStateHandleSerializer.serialize(handle, dos);
208:     }
209: 
210:     @VisibleForTesting
211:     @Override
212:     public StateObjectCollection<OutputStateHandle> deserializeResultSubpartitionStateHandle(
213:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
214:         return deserializeCollection(
215:                 dis, context, channelStateHandleSerializer::deserializeOutputStateHandle);
216:     }
217: 
218:     @VisibleForTesting
219:     @Override
220:     public void serializeInputChannelStateHandle(InputStateHandle handle, DataOutputStream dos)
221:             throws IOException {
222:         channelStateHandleSerializer.serialize(handle, dos);
223:     }
224: 
225:     @VisibleForTesting
226:     @Override
227:     public StateObjectCollection<InputStateHandle> deserializeInputChannelStateHandle(
228:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
229:         return deserializeCollection(
230:                 dis, context, channelStateHandleSerializer::deserializeInputStateHandle);
231:     }
232: 
233:     private <T extends StateObject> void serializeCollection(
234:             StateObjectCollection<T> stateObjectCollection,
235:             DataOutputStream dos,
236:             BiConsumerWithException<T, DataOutputStream, IOException> cons)
237:             throws IOException {
238:         if (stateObjectCollection == null) {
239:             dos.writeInt(0);
240:         } else {
241:             dos.writeInt(stateObjectCollection.size());
242:             for (T stateObject : stateObjectCollection) {
243:                 cons.accept(stateObject, dos);
244:             }
245:         }
246:     }
247: 
248:     // ------------------------------------------------------------------------
249:     //  exposed static methods for test cases
250:     //
251:     //  NOTE: The fact that certain tests directly call these lower level
252:     //        serialization methods is a problem, because that way the tests
253:     //        bypass the versioning scheme. Especially tests that test for
254:     //        cross-version compatibility need to version themselves if we
255:     //        ever break the format of these low level state types.
256:     // ------------------------------------------------------------------------
257: 
258:     @VisibleForTesting
259:     public static void serializeStreamStateHandle(
260:             StreamStateHandle stateHandle, DataOutputStream dos) throws IOException {
261:         MetadataV2V3SerializerBase.serializeStreamStateHandle(stateHandle, dos);
262:     }
263: 
264:     @VisibleForTesting
265:     public static StreamStateHandle deserializeStreamStateHandle(DataInputStream dis)
266:             throws IOException {
267:         return MetadataV2V3SerializerBase.deserializeStreamStateHandle(dis, null);
268:     }
269: 
270:     @VisibleForTesting
271:     public static void serializeOperatorStateHandleUtil(
272:             OperatorStateHandle stateHandle, DataOutputStream dos) throws IOException {
273:         INSTANCE.serializeOperatorStateHandle(stateHandle, dos);
274:     }
