276:     @VisibleForTesting
277:     public static OperatorStateHandle deserializeOperatorStateHandleUtil(DataInputStream dis)
278:             throws IOException {
279:         return INSTANCE.deserializeOperatorStateHandle(dis, null);
280:     }
