1083:     /**
1084:      * Test source producing (key, 0)..(key, maxValue) with key being the sub task index.
1085:      *
1086:      * <p>After all tuples have been emitted, the source waits to be cancelled and does not
1087:      * immediately finish.
1088:      */
1089:     private static class TestAscendingValueSource
1090:             extends RichParallelSourceFunction<Tuple2<Integer, Long>> {
1091: 
1092:         private static final long serialVersionUID = 1459935229498173245L;
1093: 
1094:         private final long maxValue;
1095:         private volatile boolean isRunning = true;
1096: 
1097:         TestAscendingValueSource(long maxValue) {
1098:             Preconditions.checkArgument(maxValue >= 0);
1099:             this.maxValue = maxValue;
1100:         }
1101: 
1102:         @Override
1103:         public void open(OpenContext openContext) throws Exception {
1104:             super.open(openContext);
1105:         }
1106: 
1107:         @Override
1108:         public void run(SourceContext<Tuple2<Integer, Long>> ctx) throws Exception {
1109:             // f0 => key
1110:             int key = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
1111:             Tuple2<Integer, Long> record = new Tuple2<>(key, 0L);
1112: 
1113:             long currentValue = 0;
1114:             while (isRunning && currentValue <= maxValue) {
1115:                 synchronized (ctx.getCheckpointLock()) {
1116:                     record.f1 = currentValue;
1117:                     ctx.collect(record);
1118:                 }
1119: 
1120:                 currentValue++;
1121:             }
1122: 
1123:             while (isRunning) {
1124:                 synchronized (this) {
1125:                     wait();
1126:                 }
1127:             }
