1317:         }
1318: 
1319:         @Override
1320:         public void close() throws Exception {
1321:             // Free cluster resources
1322:             clusterClient.cancel(jobId).get();
1323:             // cancel() is non-blocking so do this to make sure the job finished
1324:             CompletableFuture<JobStatus> jobStatusFuture =
1325:                     FutureUtils.retrySuccessfulWithDelay(
1326:                             () -> clusterClient.getJobStatus(jobId),
1327:                             Duration.ofMillis(50),
1328:                             deadline,
1329:                             (jobStatus) -> jobStatus.equals(JobStatus.CANCELED),
1330:                             new ScheduledExecutorServiceAdapter(EXECUTOR_EXTENSION.getExecutor()));
1331:             assertThat(jobStatusFuture.get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS))
1332:                     .isEqualTo(JobStatus.CANCELED);
1333:         }
1334:     }
