1336:     private static <K, S extends State, V> CompletableFuture<S> getKvState(
1337:             final Deadline deadline,
1338:             final QueryableStateClient client,
1339:             final JobID jobId,
1340:             final String queryName,
1341:             final K key,
1342:             final TypeInformation<K> keyTypeInfo,
1343:             final StateDescriptor<S, V> stateDescriptor,
1344:             final boolean failForUnknownKeyOrNamespace,
1345:             final ScheduledExecutor executor) {
1346: 
1347:         final CompletableFuture<S> resultFuture = new CompletableFuture<>();
1348:         getKvStateIgnoringCertainExceptions(
1349:                 deadline,
1350:                 resultFuture,
1351:                 client,
1352:                 jobId,
1353:                 queryName,
1354:                 key,
1355:                 keyTypeInfo,
1356:                 stateDescriptor,
1357:                 failForUnknownKeyOrNamespace,
1358:                 executor);
1359:         return resultFuture;
1360:     }
