1362:     private static <K, S extends State, V> void getKvStateIgnoringCertainExceptions(
1363:             final Deadline deadline,
1364:             final CompletableFuture<S> resultFuture,
1365:             final QueryableStateClient client,
1366:             final JobID jobId,
1367:             final String queryName,
1368:             final K key,
1369:             final TypeInformation<K> keyTypeInfo,
1370:             final StateDescriptor<S, V> stateDescriptor,
1371:             final boolean failForUnknownKeyOrNamespace,
1372:             final ScheduledExecutor executor) {
1373: 
1374:         if (!resultFuture.isDone()) {
1375:             CompletableFuture<S> expected =
1376:                     client.getKvState(jobId, queryName, key, keyTypeInfo, stateDescriptor);
1377:             expected.whenCompleteAsync(
1378:                     (result, throwable) -> {
1379:                         if (throwable != null) {
1380:                             if (throwable.getCause() instanceof CancellationException
1381:                                     || throwable.getCause() instanceof AssertionError
1382:                                     || (failForUnknownKeyOrNamespace
1383:                                             && throwable.getCause()
1384:                                                     instanceof UnknownKeyOrNamespaceException)) {
1385:                                 resultFuture.completeExceptionally(throwable.getCause());
1386:                             } else if (deadline.hasTimeLeft()) {
1387:                                 getKvStateIgnoringCertainExceptions(
1388:                                         deadline,
1389:                                         resultFuture,
1390:                                         client,
1391:                                         jobId,
1392:                                         queryName,
1393:                                         key,
1394:                                         keyTypeInfo,
1395:                                         stateDescriptor,
1396:                                         failForUnknownKeyOrNamespace,
1397:                                         executor);
1398:                             }
1399:                         } else {
1400:                             resultFuture.complete(result);
1401:                         }
1402:                     },
1403:                     executor);
1404: 
1405:             resultFuture.whenComplete((result, throwable) -> expected.cancel(false));
1406:         }
1407:     }
