249:     CompletableFuture<String> stopWithSavepoint(
250:             @Nullable final String targetDirectory,
251:             boolean terminate,
252:             SavepointFormatType formatType) {
253:         final ExecutionGraph executionGraph = getExecutionGraph();
254: 
255:         StopWithSavepointTerminationManager.checkSavepointActionPreconditions(
256:                 executionGraph.getCheckpointCoordinator(),
257:                 targetDirectory,
258:                 executionGraph.getJobID(),
259:                 getLogger());
260: 
261:         getLogger().info("Triggering stop-with-savepoint for job {}.", executionGraph.getJobID());
262: 
263:         CheckpointScheduling schedulingProvider = new CheckpointSchedulingProvider(executionGraph);
264: 
265:         schedulingProvider.stopCheckpointScheduler();
266: 
267:         final CompletableFuture<String> savepointFuture =
268:                 Objects.requireNonNull(executionGraph.getCheckpointCoordinator())
269:                         .triggerSynchronousSavepoint(terminate, targetDirectory, formatType)
270:                         .thenApply(CompletedCheckpoint::getExternalPointer);
271:         return context.goToStopWithSavepoint(
272:                 executionGraph,
273:                 getExecutionGraphHandler(),
274:                 getOperatorCoordinatorHandler(),
275:                 schedulingProvider,
276:                 savepointFuture,
277:                 getFailures());
278:     }
