100: 
101:         Preconditions.checkArgument(
102:                 rescaleOnFailedCheckpointCount > 0,
103:                 "The rescaleOnFailedCheckpointCount should be larger than 0.");
104:         this.maxFailedCheckpointsBeforeRescale = rescaleOnFailedCheckpointCount;
105:         this.failedCheckpointCountdown = null;
106: 
107:         deploy();
108: 
109:         // check if new resources have come available in the meantime
110:         context.runIfState(
111:                 this,
112:                 () -> {
113:                     rescaleManager.onChange();
114:                     rescaleManager.onTrigger();
115:                 },
116:                 Duration.ZERO);
117:     }
