448:                                 ((HeapLongVector)
449:                                                 ((ParquetDecimalVector) lcv.getChild()).getVector())
450:                                         .setNullAt(i);
451:                             } else {
452:                                 ((HeapLongVector)
453:                                                         ((ParquetDecimalVector) lcv.getChild())
454:                                                                 .getVector())
455:                                                 .vector[i] =
456:                                         ((List<Long>) valueList).get(i);
457:                             }
458:                         }
459:                         break;
460:                     default:
461:                         HeapBytesVector heapBytesVector = new HeapBytesVector(total);
462:                         heapBytesVector.reset();
463:                         lcv.setChild(new ParquetDecimalVector(heapBytesVector));
