103:     private boolean fetchNextValue(LogicalType type) {
104:         int left = readPageIfNeed();
105:         if (left > 0) {
106:             // get the values of repetition and definitionLevel
107:             readRepetitionAndDefinitionLevels();
108:             // read the data if it isn't null
109:             if (definitionLevel == maxDefLevel) {
110:                 if (isCurrentPageDictionaryEncoded) {
111:                     lastValue = dataColumn.readValueDictionaryId();
112:                 } else {
113:                     lastValue = readPrimitiveTypedRow(type);
114:                 }
115:             } else {
