183: 
184:         switch (type.getTypeRoot()) {
185:             case CHAR:
186:             case VARCHAR:
187:             case BINARY:
188:             case VARBINARY:
189:                 return dictionary.readBytes(dictionaryValue);
190:             case DATE:
191:             case TIME_WITHOUT_TIME_ZONE:
192:             case INTEGER:
193:                 return dictionary.readInteger(dictionaryValue);
194:             case BOOLEAN:
195:                 return dictionary.readBoolean(dictionaryValue) ? 1 : 0;
196:             case DOUBLE:
197:                 return dictionary.readDouble(dictionaryValue);
198:             case FLOAT:
199:                 return dictionary.readFloat(dictionaryValue);
200:             case TINYINT:
201:                 return dictionary.readTinyInt(dictionaryValue);
202:             case SMALLINT:
203:                 return dictionary.readSmallInt(dictionaryValue);
204:             case BIGINT:
205:                 return dictionary.readLong(dictionaryValue);
206:             case DECIMAL:
207:                 switch (descriptor.getPrimitiveType().getPrimitiveTypeName()) {
208:                     case INT32:
209:                         return dictionary.readInteger(dictionaryValue);
210:                     case INT64:
211:                         return dictionary.readLong(dictionaryValue);
212:                     case FIXED_LEN_BYTE_ARRAY:
213:                     case BINARY:
214:                         return dictionary.readBytes(dictionaryValue);
215:                 }
216:             case TIMESTAMP_WITHOUT_TIME_ZONE:
217:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
