592:     /** Writes state to test whether the sink can read from alternative state names. */
593:     private static class CompatibleStateSinkOperator<T> extends AbstractStreamOperator<String>
594:             implements OneInputStreamOperator<String, String> {
595: 
596:         static final String SINK_STATE_NAME = "compatible_sink_state";
597: 
598:         static final ListStateDescriptor<byte[]> SINK_STATE_DESC =
599:                 new ListStateDescriptor<>(SINK_STATE_NAME, BytePrimitiveArraySerializer.INSTANCE);
600:         ListState<T> sinkState;
601:         private final SimpleVersionedSerializer<T> serializer;
602:         private final T initialState;
603: 
604:         public CompatibleStateSinkOperator(
605:                 SimpleVersionedSerializer<T> serializer, T initialState) {
606:             this.serializer = serializer;
607:             this.initialState = initialState;
608:         }
609: 
610:         public void initializeState(StateInitializationContext context) throws Exception {
611:             super.initializeState(context);
612:             sinkState =
613:                     new SimpleVersionedListState<>(
614:                             context.getOperatorStateStore().getListState(SINK_STATE_DESC),
615:                             serializer);
616:             if (!context.isRestored()) {
617:                 sinkState.add(initialState);
618:             }
619:         }
