77: /**
78:  * This rule checks if a {@link UnresolvedCallExpression} can work with the given arguments and
79:  * infers the output data type. All function calls are resolved {@link CallExpression} after
80:  * applying this rule.
81:  *
82:  * <p>This rule also resolves {@code flatten()} calls on composite types.
83:  *
84:  * <p>If the call expects different types of arguments, but the given arguments have types that can
85:  * be cast, a {@link BuiltInFunctionDefinitions#CAST} expression is inserted.
86:  *
87:  * <p>It validates and prepares inline, unregistered {@link UserDefinedFunction}s.
88:  */
89: @Internal
90: final class ResolveCallByArgumentsRule implements ResolverRule {
91: 
92:     @Override
93:     public List<Expression> apply(List<Expression> inputExpressions, ResolutionContext context) {
94:         // only the top-level expressions may access the output data type
95:         final SurroundingInfo surroundingInfo =
96:                 context.getOutputDataType().map(SurroundingInfo::of).orElse(null);
97:         return inputExpressions.stream()
98:                 .flatMap(inputExpr -> inputExpr
99:                         .accept(new ResolvingCallVisitor(context, surroundingInfo)).stream())
100:                 .collect(Collectors.toList());
101:     }
102: 
103:     // --------------------------------------------------------------------------------------------
104: 
105:     private static class ResolvingCallVisitor
106:             extends RuleExpressionVisitor<List<ResolvedExpression>> {
107: 
108:         private final @Nullable SurroundingInfo surroundingInfo;
109: 
110:         ResolvingCallVisitor(ResolutionContext context, @Nullable SurroundingInfo surroundingInfo) {
111:             super(context);
112:             this.surroundingInfo = surroundingInfo;
113:         }
114: 
115:         @Override
116:         public List<ResolvedExpression> visit(UnresolvedCallExpression unresolvedCall) {
117:             final FunctionDefinition definition;
118:             // clean functions that were not registered in a catalog
119:             if (unresolvedCall.getFunctionIdentifier().isEmpty()) {
120:                 definition =
121:                         prepareInlineUserDefinedFunction(unresolvedCall.getFunctionDefinition());
122:             } else {
123:                 definition = unresolvedCall.getFunctionDefinition();
124:             }
125: 
126:             final String functionName =
127:                     unresolvedCall
128:                             .getFunctionIdentifier()
129:                             .map(FunctionIdentifier::toString)
130:                             .orElseGet(definition::toString);
131: 
132:             final TypeInference typeInference = getTypeInferenceOrNull(definition);
133: 
134:             // Reorder named arguments and add replacements for optional ones
135:             final UnresolvedCallExpression adaptedCall =
136:                     executeAssignment(functionName, definition, typeInference, unresolvedCall);
137: 
138:             // resolve the children with information from the current call
139:             final List<ResolvedExpression> resolvedArgs = new ArrayList<>();
140:             final int argumentCount = adaptedCall.getChildren().size();
141: 
142:             for (int argumentIndex = 0; argumentIndex < argumentCount; argumentIndex++) {
143:                 final SurroundingInfo surroundingInfo;
144:                 if (typeInference == null) {
145:                     surroundingInfo = null;
146:                 } else {
147:                     surroundingInfo =
148:                             SurroundingInfo.of(
149:                                     functionName,
150:                                     definition,
151:                                     typeInference,
152:                                     argumentCount,
153:                                     argumentIndex,
154:                                     resolutionContext.isGroupedAggregation());
155:                 }
156:                 final ResolvingCallVisitor childResolver =
157:                         new ResolvingCallVisitor(resolutionContext, surroundingInfo);
158:                 resolvedArgs.addAll(adaptedCall.getChildren().get(argumentIndex).accept(childResolver));
159:             }
160: 
161:             if (definition == BuiltInFunctionDefinitions.FLATTEN) {
162:                 return executeFlatten(resolvedArgs);
163:             }
164: 
165:             return Collections.singletonList(
166:                     runTypeInference(
167:                             functionName,
168:                             adaptedCall,
169:                             typeInference,
170:                             resolvedArgs,
171:                             surroundingInfo));
172:         }
173: 
174:         @Override
175:         protected List<ResolvedExpression> defaultMethod(Expression expression) {
176:             if (expression instanceof ResolvedExpression) {
177:                 return Collections.singletonList((ResolvedExpression) expression);
178:             }
179:             throw new TableException("Unexpected unresolved expression: " + expression);
180:         }
181: 
182:         private List<ResolvedExpression> executeFlatten(List<ResolvedExpression> resolvedArguments) {
183:             if (resolvedArguments.size() != 1) {
184:                 throw new ValidationException("Invalid number of arguments for flattening.");
185:             }
186:             final ResolvedExpression composite = resolvedArguments.get(0);
187:             final LogicalType compositeType = composite.getOutputDataType().getLogicalType();
188:             if (hasLegacyTypes(compositeType)) {
189:                 return flattenLegacyCompositeType(composite);
190:             }
191:             return flattenCompositeType(composite);
192:         }
193: 
194:         private List<ResolvedExpression> flattenCompositeType(ResolvedExpression composite) {
195:             final DataType dataType = composite.getOutputDataType();
196:             final LogicalType type = dataType.getLogicalType();
197:             if (!isCompositeType(type)) {
198:                 return singletonList(composite);
199:             }
200:             final List<DataType> fieldDataTypes = DataTypeUtils.flattenToDataTypes(dataType);
201:             final List<String> fieldNames = DataTypeUtils.flattenToNames(dataType);
202:             return IntStream.range(0, fieldDataTypes.size())
203:                     .mapToObj(
204:                             idx -> {
205:                                 final DataType fieldDataType = fieldDataTypes.get(idx);
206:                                 final DataType nullableFieldDataType;
207:                                 if (type.isNullable()) {
208:                                     nullableFieldDataType = fieldDataType.nullable();
209:                                 } else {
210:                                     nullableFieldDataType = fieldDataType;
211:                                 }
212:                                 return resolutionContext
213:                                         .postResolutionFactory()
214:                                         .get(
215:                                                 composite,
216:                                                 valueLiteral(fieldNames.get(idx)),
217:                                                 nullableFieldDataType);
218:                             })
219:                     .collect(Collectors.toList());
220:         }
221: 
222:         private List<ResolvedExpression> flattenLegacyCompositeType(ResolvedExpression composite) {
223:             final TypeInformation<?> resultType =
224:                     fromDataTypeToLegacyInfo(composite.getOutputDataType());
225:             if (!(resultType instanceof CompositeType)) {
226:                 return singletonList(composite);
227:             }
228:             final CompositeType<?> compositeType = (CompositeType<?>) resultType;
229:             return IntStream.range(0, resultType.getArity())
230:                     .mapToObj(
231:                             idx ->
232:                                     resolutionContext
233:                                             .postResolutionFactory()
234:                                             .get(
235:                                                     composite,
236:                                                     valueLiteral(
237:                                                             compositeType.getFieldNames()[idx]),
238:                                                     fromLegacyInfoToDataType(
239:                                                             compositeType.getTypeAt(idx))))
240:                     .collect(Collectors.toList());
241:         }
242: 
243:         /** Temporary method until all calls define a type inference. */
244:         private @Nullable TypeInference getTypeInferenceOrNull(FunctionDefinition definition) {
245:             final TypeInference inference =
246:                     definition.getTypeInference(resolutionContext.typeFactory());
247:             if (inference.getOutputTypeStrategy() != TypeStrategies.MISSING) {
248:                 return inference;
249:             } else {
250:                 return null;
251:             }
252:         }
253: 
254:         private UnresolvedCallExpression executeAssignment(
255:                 String functionName,
256:                 FunctionDefinition definition,
257:                 @Nullable TypeInference inference,
258:                 UnresolvedCallExpression unresolvedCall) {
259:             // Assignment cannot be a top-level expression,
260:             // it must be located within a function call
261:             if (definition == BuiltInFunctionDefinitions.ASSIGNMENT) {
262:                 throw new ValidationException(
263:                         "Named arguments via asArgument() can only be used within function calls.");
264:             }
265:             // Skip assignment for special calls
266:             if (inference == null) {
267:                 return unresolvedCall;
268:             }
269: 
270:             final List<Expression> actualArgs = unresolvedCall.getChildren();
271:             final Map<String, Expression> namedArgs = new HashMap<>();
272:             actualArgs.stream()
273:                     .map(this::extractAssignment)
274:                     .filter(Objects::nonNull)
275:                     .forEach(
276:                             assignment -> {
277:                                 if (namedArgs.containsKey(assignment.getKey())) {
278:                                     throw new ValidationException(
279:                                             String.format(
280:                                                     "Invalid call to function '%s'. "
281:                                                             + "Duplicate named argument found: %s",
282:                                                     functionName, assignment.getKey()));
283:                                 }
284:                                 namedArgs.put(assignment.getKey(), assignment.getValue());
285:                             });
286:             if (namedArgs.isEmpty()) {
287:                 // Use position-based call
288:                 return unresolvedCall;
289:             }
290: 
291:             final List<StaticArgument> declaredArgs = inference.getStaticArguments().orElse(null);
292:             if (declaredArgs == null) {
293:                 throw new ValidationException(
294:                         String.format(
295:                                 "Invalid call to function '%s'. "
296:                                         + "The function does not support named arguments. "
297:                                         + "Please pass the arguments based on positions (i.e. without asArgument()).",
298:                                 functionName));
299:             }
300: 
301:             // Fill optional arguments
302:             declaredArgs.forEach(
303:                     declaredArg -> {
304:                         if (declaredArg.isOptional()) {
305:                             // All optional arguments have a type.
306:                             // This is checked in StaticArgument.
307:                             final DataType dataType =
308:                                     declaredArg
309:                                             .getDataType()
310:                                             .orElseThrow(IllegalStateException::new);
311:                             namedArgs.putIfAbsent(
312:                                     declaredArg.getName(),
313:                                     CallExpression.permanent(
314:                                             BuiltInFunctionDefinitions.DEFAULT,
315:                                             List.of(),
316:                                             dataType));
317:                         }
318:                     });
319: 
320:             if (declaredArgs.size() != namedArgs.size()) {
321:                 final Set<String> providedArgs = namedArgs.keySet();
322:                 final Set<String> knownArgs =
323:                         declaredArgs.stream()
324:                                 .map(StaticArgument::getName)
325:                                 .collect(Collectors.toSet());
326:                 final Set<String> unknownArgs =
327:                         providedArgs.stream()
328:                                 .filter(arg -> !knownArgs.contains(arg))
329:                                 .collect(Collectors.toSet());
330:                 final String cause;
331:                 if (!unknownArgs.isEmpty()) {
332:                     cause = "Unknown argument names: " + unknownArgs;
333:                 } else {
334:                     final List<StaticArgument> missingArgs =
335:                             declaredArgs.stream()
336:                                     .filter(arg -> !providedArgs.contains(arg.getName()))
337:                                     .collect(Collectors.toList());
338:                     cause = "Missing required arguments: " + missingArgs;
339:                 }
340:                 throw new ValidationException(
341:                         String.format(
342:                                 "Invalid call to function '%s'. If the call uses named arguments, "
343:                                         + "a valid name has to be provided for all passed arguments. %s",
344:                                 functionName, cause));
345:             }
346: 
347:             final List<Expression> reorderedArgs =
348:                     declaredArgs.stream()
349:                             .map(arg -> namedArgs.get(arg.getName()))
350:                             .collect(Collectors.toList());
351:             return unresolvedCall.replaceArgs(reorderedArgs);
352:         }
353: 
354:         private Map.Entry<String, Expression> extractAssignment(Expression e) {
355:             final List<Expression> children = e.getChildren();
356:             if (!isFunction(e, BuiltInFunctionDefinitions.ASSIGNMENT) || children.size() != 2) {
357:                 return null;
358:             }
359:             final String name = ExpressionUtils.stringValue(children.get(0));
360:             if (name == null) {
361:                 return null;
362:             }
363:             return Map.entry(name, children.get(1));
364:         }
365: 
366:         private ResolvedExpression runTypeInference(
367:                 String functionName,
368:                 UnresolvedCallExpression unresolvedCall,
369:                 TypeInference inference,
370:                 List<ResolvedExpression> resolvedArgs,
371:                 @Nullable SurroundingInfo surroundingInfo) {
372:             if (inference == null) {
373:                 throw new TableException(
374:                         "Could not get a type inference for function: " + functionName);
375:             }
376: 
377:             final Result inferenceResult =
378:                     TypeInferenceUtil.runTypeInference(
379:                             inference,
380:                             new TableApiCallContext(
381:                                     resolutionContext.typeFactory(),
382:                                     functionName,
383:                                     unresolvedCall.getFunctionDefinition(),
384:                                     resolvedArgs,
385:                                     resolutionContext.isGroupedAggregation()),
386:                             surroundingInfo);
387: 
388:             final List<ResolvedExpression> adaptedArguments =
389:                     castArguments(inferenceResult, resolvedArgs);
390: 
391:             return unresolvedCall.resolve(adaptedArguments, inferenceResult.getOutputDataType());
392:         }
393: 
394:         /** Casts the arguments according to the properties of the {@link Result}. */
395:         private List<ResolvedExpression> castArguments(
396:                 Result inferenceResult, List<ResolvedExpression> resolvedArgs) {
397: 
398:             return IntStream.range(0, resolvedArgs.size())
399:                     .mapToObj(
400:                             pos -> {
401:                                 final ResolvedExpression argument = resolvedArgs.get(pos);
402:                                 final DataType argumentType = argument.getOutputDataType();
403:                                 final DataType expectedType =
404:                                         inferenceResult.getExpectedArgumentTypes().get(pos);
405: 
406:                                 if (!supportsAvoidingCast(
407:                                         argumentType.getLogicalType(),
408:                                         expectedType.getLogicalType())) {
409:                                     return resolutionContext
410:                                             .postResolutionFactory()
411:                                             .cast(argument, expectedType);
412:                                 }
413:                                 return argument;
414:                             })
415:                     .collect(Collectors.toList());
416:         }
