104: 
105:     private static class ResolvingCallVisitor
106:             extends RuleExpressionVisitor<List<ResolvedExpression>> {
107: 
108:         private final @Nullable SurroundingInfo surroundingInfo;
109: 
110:         ResolvingCallVisitor(ResolutionContext context, @Nullable SurroundingInfo surroundingInfo) {
111:             super(context);
112:             this.surroundingInfo = surroundingInfo;
113:         }
114: 
115:         @Override
116:         public List<ResolvedExpression> visit(UnresolvedCallExpression unresolvedCall) {
117:             final FunctionDefinition definition;
118:             // clean functions that were not registered in a catalog
119:             if (unresolvedCall.getFunctionIdentifier().isEmpty()) {
120:                 definition =
121:                         prepareInlineUserDefinedFunction(unresolvedCall.getFunctionDefinition());
122:             } else {
123:                 definition = unresolvedCall.getFunctionDefinition();
124:             }
125: 
126:             final String functionName =
127:                     unresolvedCall
128:                             .getFunctionIdentifier()
129:                             .map(FunctionIdentifier::toString)
130:                             .orElseGet(definition::toString);
131: 
132:             final TypeInference typeInference = getTypeInferenceOrNull(definition);
133: 
134:             // Reorder named arguments and add replacements for optional ones
135:             final UnresolvedCallExpression adaptedCall =
136:                     executeAssignment(functionName, definition, typeInference, unresolvedCall);
137: 
138:             // resolve the children with information from the current call
139:             final List<ResolvedExpression> resolvedArgs = new ArrayList<>();
140:             final int argumentCount = adaptedCall.getChildren().size();
141: 
142:             for (int argumentIndex = 0; argumentIndex < argumentCount; argumentIndex++) {
143:                 final SurroundingInfo surroundingInfo;
144:                 if (typeInference == null) {
145:                     surroundingInfo = null;
146:                 } else {
147:                     surroundingInfo =
148:                             SurroundingInfo.of(
149:                                     functionName,
150:                                     definition,
151:                                     typeInference,
152:                                     argumentCount,
153:                                     argumentIndex,
154:                                     resolutionContext.isGroupedAggregation());
155:                 }
156:                 final ResolvingCallVisitor childResolver =
157:                         new ResolvingCallVisitor(resolutionContext, surroundingInfo);
158:                 resolvedArgs.addAll(adaptedCall.getChildren().get(argumentIndex).accept(childResolver));
159:             }
160: 
161:             if (definition == BuiltInFunctionDefinitions.FLATTEN) {
162:                 return executeFlatten(resolvedArgs);
163:             }
164: 
165:             return Collections.singletonList(
166:                     runTypeInference(
167:                             functionName,
168:                             adaptedCall,
169:                             typeInference,
170:                             resolvedArgs,
171:                             surroundingInfo));
172:         }
173: 
174:         @Override
175:         protected List<ResolvedExpression> defaultMethod(Expression expression) {
176:             if (expression instanceof ResolvedExpression) {
177:                 return Collections.singletonList((ResolvedExpression) expression);
178:             }
179:             throw new TableException("Unexpected unresolved expression: " + expression);
180:         }
