182:         private List<ResolvedExpression> executeFlatten(List<ResolvedExpression> resolvedArguments) {
183:             if (resolvedArguments.size() != 1) {
184:                 throw new ValidationException("Invalid number of arguments for flattening.");
185:             }
186:             final ResolvedExpression composite = resolvedArguments.get(0);
187:             final LogicalType compositeType = composite.getOutputDataType().getLogicalType();
188:             if (hasLegacyTypes(compositeType)) {
189:                 return flattenLegacyCompositeType(composite);
190:             }
191:             return flattenCompositeType(composite);
192:         }
193: 
194:         private List<ResolvedExpression> flattenCompositeType(ResolvedExpression composite) {
195:             final DataType dataType = composite.getOutputDataType();
196:             final LogicalType type = dataType.getLogicalType();
197:             if (!isCompositeType(type)) {
198:                 return singletonList(composite);
199:             }
200:             final List<DataType> fieldDataTypes = DataTypeUtils.flattenToDataTypes(dataType);
201:             final List<String> fieldNames = DataTypeUtils.flattenToNames(dataType);
202:             return IntStream.range(0, fieldDataTypes.size())
203:                     .mapToObj(
204:                             idx -> {
205:                                 final DataType fieldDataType = fieldDataTypes.get(idx);
206:                                 final DataType nullableFieldDataType;
207:                                 if (type.isNullable()) {
208:                                     nullableFieldDataType = fieldDataType.nullable();
209:                                 } else {
210:                                     nullableFieldDataType = fieldDataType;
211:                                 }
212:                                 return resolutionContext
213:                                         .postResolutionFactory()
214:                                         .get(
215:                                                 composite,
216:                                                 valueLiteral(fieldNames.get(idx)),
217:                                                 nullableFieldDataType);
218:                             })
219:                     .collect(Collectors.toList());
220:         }
221: 
222:         private List<ResolvedExpression> flattenLegacyCompositeType(ResolvedExpression composite) {
223:             final TypeInformation<?> resultType =
224:                     fromDataTypeToLegacyInfo(composite.getOutputDataType());
225:             if (!(resultType instanceof CompositeType)) {
226:                 return singletonList(composite);
227:             }
228:             final CompositeType<?> compositeType = (CompositeType<?>) resultType;
229:             return IntStream.range(0, resultType.getArity())
230:                     .mapToObj(
231:                             idx ->
232:                                     resolutionContext
233:                                             .postResolutionFactory()
234:                                             .get(
235:                                                     composite,
236:                                                     valueLiteral(
237:                                                             compositeType.getFieldNames()[idx]),
238:                                                     fromLegacyInfoToDataType(
239:                                                             compositeType.getTypeAt(idx))))
240:                     .collect(Collectors.toList());
241:         }
242: 
243:         /** Temporary method until all calls define a type inference. */
244:         private @Nullable TypeInference getTypeInferenceOrNull(FunctionDefinition definition) {
245:             final TypeInference inference =
246:                     definition.getTypeInference(resolutionContext.typeFactory());
247:             if (inference.getOutputTypeStrategy() != TypeStrategies.MISSING) {
248:                 return inference;
249:             } else {
250:                 return null;
251:             }
252:         }
