354:         private Map.Entry<String, Expression> extractAssignment(Expression e) {
355:             final List<Expression> children = e.getChildren();
356:             if (!isFunction(e, BuiltInFunctionDefinitions.ASSIGNMENT) || children.size() != 2) {
357:                 return null;
358:             }
359:             final String name = ExpressionUtils.stringValue(children.get(0));
360:             if (name == null) {
361:                 return null;
362:             }
363:             return Map.entry(name, children.get(1));
364:         }
