418:         /** Validates and cleans an inline, unregistered {@link UserDefinedFunction}. */
419:         private FunctionDefinition prepareInlineUserDefinedFunction(FunctionDefinition definition) {
420:             if (definition instanceof ScalarFunctionDefinition) {
421:                 final ScalarFunctionDefinition sf = (ScalarFunctionDefinition) definition;
422:                 UserDefinedFunctionHelper.prepareInstance(
423:                         resolutionContext.configuration(), sf.getScalarFunction());
424:                 return new ScalarFunctionDefinition(sf.getName(), sf.getScalarFunction());
425:             } else if (definition instanceof TableFunctionDefinition) {
426:                 final TableFunctionDefinition tf = (TableFunctionDefinition) definition;
427:                 UserDefinedFunctionHelper.prepareInstance(
428:                         resolutionContext.configuration(), tf.getTableFunction());
429:                 return new TableFunctionDefinition(
430:                         tf.getName(), tf.getTableFunction(), tf.getResultType());
431:             } else if (definition instanceof AggregateFunctionDefinition) {
432:                 final AggregateFunctionDefinition af = (AggregateFunctionDefinition) definition;
433:                 UserDefinedFunctionHelper.prepareInstance(
434:                         resolutionContext.configuration(), af.getAggregateFunction());
435:                 return new AggregateFunctionDefinition(
436:                         af.getName(),
437:                         af.getAggregateFunction(),
438:                         af.getResultTypeInfo(),
439:                         af.getAccumulatorTypeInfo());
440:             } else if (definition instanceof TableAggregateFunctionDefinition) {
441:                 final TableAggregateFunctionDefinition taf =
442:                         (TableAggregateFunctionDefinition) definition;
443:                 UserDefinedFunctionHelper.prepareInstance(
444:                         resolutionContext.configuration(), taf.getTableAggregateFunction());
445:                 return new TableAggregateFunctionDefinition(
446:                         taf.getName(),
447:                         taf.getTableAggregateFunction(),
448:                         taf.getResultTypeInfo(),
449:                         taf.getAccumulatorTypeInfo());
450:             } else if (definition instanceof UserDefinedFunction) {
451:                 UserDefinedFunctionHelper.prepareInstance(
452:                         resolutionContext.configuration(), (UserDefinedFunction) definition);
453:             }
454:             return definition;
455:         }
456:     }
