460:     private static class TableApiCallContext implements CallContext {
461: 
462:         private final DataTypeFactory typeFactory;
463: 
464:         private final String name;
465: 
466:         private final FunctionDefinition definition;
467: 
468:         private final List<ResolvedExpression> resolvedArgs;
469: 
470:         private final boolean isGroupedAggregation;
471: 
472:         public TableApiCallContext(
473:                 DataTypeFactory typeFactory,
474:                 String functionName,
475:                 FunctionDefinition definition,
476:                 List<ResolvedExpression> resolvedArgs,
477:                 boolean isGroupedAggregation) {
478:             this.typeFactory = typeFactory;
479:             this.name = functionName;
480:             this.definition = definition;
481:             this.resolvedArgs = resolvedArgs;
482:             this.isGroupedAggregation = isGroupedAggregation;
483:         }
484: 
485:         @Override
486:         public DataTypeFactory getDataTypeFactory() {
487:             return typeFactory;
488:         }
489: 
490:         @Override
491:         public FunctionDefinition getFunctionDefinition() {
492:             return definition;
493:         }
494: 
495:         @Override
496:         public boolean isArgumentLiteral(int pos) {
497:             final ResolvedExpression arg = getArgument(pos);
498:             return arg instanceof ValueLiteralExpression || arg instanceof TypeLiteralExpression;
499:         }
500: 
501:         @Override
502:         public boolean isArgumentNull(int pos) {
503:             final ResolvedExpression arg = getArgument(pos);
504:             if (isFunction(arg, BuiltInFunctionDefinitions.DEFAULT)) {
505:                 return true;
506:             }
507:             if (arg instanceof ValueLiteralExpression) {
508:                 final ValueLiteralExpression literal = (ValueLiteralExpression) arg;
509:                 return literal.isNull();
510:             }
511:             return false;
512:         }
513: 
514:         @Override
515:         @SuppressWarnings("unchecked")
516:         public <T> Optional<T> getArgumentValue(int pos, Class<T> clazz) {
517:             final ResolvedExpression arg = getArgument(pos);
518:             if (arg instanceof TypeLiteralExpression) {
519:                 if (!DataType.class.isAssignableFrom(clazz)) {
520:                     return Optional.empty();
521:                 }
522:                 return Optional.of((T) arg.getOutputDataType());
523:             }
524:             if (arg instanceof ValueLiteralExpression) {
525:                 final ValueLiteralExpression literal = (ValueLiteralExpression) arg;
526:                 return literal.getValueAs(clazz);
527:             }
528:             return Optional.empty();
529:         }
530: 
531:         @Override
532:         public String getName() {
533:             return name;
534:         }
535: 
536:         @Override
537:         public List<DataType> getArgumentDataTypes() {
538:             return resolvedArgs.stream()
539:                     .map(ResolvedExpression::getOutputDataType)
540:                     .collect(Collectors.toList());
541:         }
542: 
543:         @Override
544:         public Optional<DataType> getOutputDataType() {
545:             return Optional.empty();
546:         }
547: 
548:         @Override
549:         public boolean isGroupedAggregation() {
550:             return isGroupedAggregation;
551:         }
552: 
553:         private ResolvedExpression getArgument(int pos) {
554:             if (pos >= resolvedArgs.size()) {
555:                 throw new IndexOutOfBoundsException(
556:                         String.format(
557:                                 "Not enough arguments to access literal at position %d for function '%s'.",
558:                                 pos, name));
559:             }
560:             return resolvedArgs.get(pos);
561:         }
562:     }
