275:                     .forEach(
276:                             assignment -> {
277:                                 if (namedArgs.containsKey(assignment.getKey())) {
278:                                     throw new ValidationException(
279:                                             String.format(
280:                                                     "Invalid call to function '%s'. "
281:                                                             + "Duplicate named argument found: %s",
282:                                                     functionName, assignment.getKey()));
283:                                 }
284:                                 namedArgs.put(assignment.getKey(), assignment.getValue());
