354:         private Map.Entry<String, Expression> extractAssignment(Expression expr) {
355:             final List<Expression> children = expr.getChildren();
356:             if (!isFunction(expr, BuiltInFunctionDefinitions.ASSIGNMENT) || children.size() != 2) {
