311:                             namedArgs.putIfAbsent(
312:                                     declaredArg.getName(),
313:                                     CallExpression.permanent(
314:                                             BuiltInFunctionDefinitions.DEFAULT,
315:                                             List.of(),
316:                                             dataType));
