254:         private UnresolvedCallExpression executeAssignment(
255:                 String functionName,
256:                 FunctionDefinition definition,
257:                 @Nullable TypeInference inference,
258:                 UnresolvedCallExpression unresolvedCall) {
259:             // Assignment cannot be a top-level expression,
260:             // it must be located within a function call
261:             if (definition == BuiltInFunctionDefinitions.ASSIGNMENT) {
262:                 throw new ValidationException(
263:                         "Named arguments via asArgument() can only be used within function calls.");
264:             }
265:             // Skip assignment for special calls
266:             if (inference == null) {
267:                 return unresolvedCall;
268:             }
269: 
270:             final List<Expression> originalArguments = unresolvedCall.getChildren();
271:             final Map<String, Expression> namedArgs = new HashMap<>();
272:             originalArguments.stream()
273:                     .map(this::extractAssignment)
274:                     .filter(Objects::nonNull)
275:                     .forEach(
276:                             assignment -> {
277:                                 if (namedArgs.containsKey(assignment.getKey())) {
278:                                     throw new ValidationException(
279:                                             String.format(
280:                                                     "Invalid call to function '%s'. "
281:                                                             + "Duplicate named argument found: %s",
282:                                                     functionName, assignment.getKey()));
283:                                 }
284:                                 namedArgs.put(assignment.getKey(), assignment.getValue());
285:                             });
286:             if (namedArgs.isEmpty()) {
287:                 // Use position-based call
288:                 return unresolvedCall;
289:             }
290: 
291:             final List<StaticArgument> declaredArgs = inference.getStaticArguments().orElse(null);
292:             if (declaredArgs == null) {
293:                 throw new ValidationException(
294:                         String.format(
295:                                 "Invalid call to function '%s'. "
296:                                         + "The function does not support named arguments. "
297:                                         + "Please pass the arguments based on positions (i.e. without asArgument()).",
298:                                 functionName));
299:             }
300: 
301:             // Fill optional arguments
302:             declaredArgs.forEach(
303:                     declaredArg -> {
304:                         if (declaredArg.isOptional()) {
305:                             // All optional arguments have a type.
306:                             // This is checked in StaticArgument.
307:                             final DataType dataType =
308:                                     declaredArg
309:                                             .getDataType()
310:                                             .orElseThrow(IllegalStateException::new);
311:                             namedArgs.putIfAbsent(
312:                                     declaredArg.getName(),
313:                                     CallExpression.permanent(
314:                                             BuiltInFunctionDefinitions.DEFAULT,
315:                                             List.of(),
316:                                             dataType));
317:                         }
318:                     });
319: 
320:             if (declaredArgs.size() != namedArgs.size()) {
321:                 final Set<String> providedArgs = namedArgs.keySet();
322:                 final Set<String> knownArgs =
323:                         declaredArgs.stream()
324:                                 .map(StaticArgument::getName)
325:                                 .collect(Collectors.toSet());
326:                 final Set<String> unknownArgs =
327:                         providedArgs.stream()
328:                                 .filter(arg -> !knownArgs.contains(arg))
329:                                 .collect(Collectors.toSet());
330:                 final String cause;
331:                 if (!unknownArgs.isEmpty()) {
332:                     cause = "Unknown argument names: " + unknownArgs;
333:                 } else {
334:                     final List<StaticArgument> missingArgs =
335:                             declaredArgs.stream()
336:                                     .filter(arg -> !providedArgs.contains(arg.getName()))
337:                                     .collect(Collectors.toList());
338:                     cause = "Missing required arguments: " + missingArgs;
339:                 }
340:                 throw new ValidationException(
341:                         String.format(
342:                                 "Invalid call to function '%s'. If the call uses named arguments, "
343:                                         + "a valid name has to be provided for all passed arguments. %s",
344:                                 functionName, cause));
345:             }
346: 
347:             final List<Expression> reorderedArgs =
348:                     declaredArgs.stream()
349:                             .map(arg -> namedArgs.get(arg.getName()))
350:                             .collect(Collectors.toList());
351:             return unresolvedCall.replaceArgs(reorderedArgs);
352:         }
353: 
354:         private Map.Entry<String, Expression> extractAssignment(Expression expr) {
355:             final List<Expression> childExpressions = expr.getChildren();
356:             if (!isFunction(expr, BuiltInFunctionDefinitions.ASSIGNMENT) || childExpressions.size() != 2) {
357:                 return null;
358:             }
359:             final String name = ExpressionUtils.stringValue(childExpressions.get(0));
360:             if (name == null) {
361:                 return null;
362:             }
363:             return Map.entry(name, childExpressions.get(1));
364:         }
