366:         private ResolvedExpression runTypeInference(
367:                 String functionName,
368:                 UnresolvedCallExpression unresolvedCall,
369:                 TypeInference inference,
370:                 List<ResolvedExpression> resolvedArgs,
371:                 @Nullable SurroundingInfo surroundingInfo) {
372:             if (inference == null) {
373:                 throw new TableException(
374:                         "Could not get a type inference for function: " + functionName);
375:             }
376: 
377:             final Result inferenceResult =
378:                     TypeInferenceUtil.runTypeInference(
379:                             inference,
380:                             new TableApiCallContext(
381:                                     resolutionContext.typeFactory(),
382:                                     functionName,
383:                                     unresolvedCall.getFunctionDefinition(),
384:                                     resolvedArgs,
385:                                     resolutionContext.isGroupedAggregation()),
386:                             surroundingInfo);
387: 
388:             final List<ResolvedExpression> adaptedArguments =
389:                     castArguments(inferenceResult, resolvedArgs);
390: 
391:             return unresolvedCall.resolve(adaptedArguments, inferenceResult.getOutputDataType());
392:         }
393: 
394:         /** Casts the arguments according to the properties of the {@link Result}. */
395:         private List<ResolvedExpression> castArguments(
396:                 Result inferenceResult, List<ResolvedExpression> resolvedArgs) {
397: 
398:             return IntStream.range(0, resolvedArgs.size())
399:                     .mapToObj(
400:                             pos -> {
401:                                 final ResolvedExpression argument = resolvedArgs.get(pos);
402:                                 final DataType argumentType = argument.getOutputDataType();
403:                                 final DataType expectedType =
404:                                         inferenceResult.getExpectedArgumentTypes().get(pos);
405: 
406:                                 if (!supportsAvoidingCast(
407:                                         argumentType.getLogicalType(),
408:                                         expectedType.getLogicalType())) {
409:                                     return resolutionContext
410:                                             .postResolutionFactory()
411:                                             .cast(argument, expectedType);
412:                                 }
413:                                 return argument;
414:                             })
415:                     .collect(Collectors.toList());
416:         }
