584:     /**
585:      * A special map function which can get tasks' information (Such as {@link ResultPartitionID})
586:      * and manually control the task's execution.
587:      */
588:     private static class StubMapFunction extends AbstractStreamOperator<Tuple2<Integer, Integer>>
589:             implements OneInputStreamOperator<Long, Tuple2<Integer, Integer>> {
590: 
591:         public static Map<Integer, Boolean> subtaskBlocked = new ConcurrentHashMap<>();
592:         public static Map<Integer, Integer> attemptIds = new ConcurrentHashMap<>();
593: 
594:         @Override
595:         protected void setup(
596:                 StreamTask<?, ?> containingTask,
597:                 StreamConfig config,
598:                 Output<StreamRecord<Tuple2<Integer, Integer>>> output) {
599:             super.setup(containingTask, config, output);
600: 
601:             int subIdx = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
602: 
603:             // attempt id ++
604:             attemptIds.compute(
605:                     subIdx,
606:                     (ignored, value) -> {
607:                         if (value == null) {
608:                             value = 0;
609:                         } else {
610:                             value += 1;
611:                         }
612:                         return value;
613:                     });
614: 
615:             // wait until unblocked.
616:             if (subtaskBlocked.containsKey(subIdx) && subtaskBlocked.get(subIdx)) {
617:                 tryWaitUntilCondition(() -> !subtaskBlocked.get(subIdx));
618:             }
619:         }
620: 
621:         @Override
622:         public void processElement(StreamRecord<Long> streamRecord) throws Exception {
623:             int number = streamRecord.getValue().intValue();
624:             output.collect(new StreamRecord<>(new Tuple2<>(number % NUMBER_KEYS, 1)));
625:         }
626: 
627:         public static void clear() {
628:             subtaskBlocked.clear();
629:             attemptIds.clear();
630:         }
631: 
632:         public static void blockSubTasks(Integer... subIndices) {
633:             setSubtaskBlocked(Arrays.asList(subIndices), true, subtaskBlocked);
634:         }
635: 
636:         public static void unblockSubTasks(Integer... subIndices) {
637:             setSubtaskBlocked(Arrays.asList(subIndices), false, subtaskBlocked);
638:         }
639:     }
