99:                 getDataSet(env).reduce(new OverwriteObjectsReduce(false)).collect().get(0);
100: 
101:         env.getConfig().disableObjectReuse();
102: 
103:         Tuple2<IntValue, IntValue> disabledResult =
104:                 getDataSet(env).reduce(new OverwriteObjectsReduce(false)).collect().get(0);
105: 
106:         Assert.assertEquals(NUMBER_OF_ELEMENTS, enabledResult.f1.getValue());
107:         Assert.assertEquals(NUMBER_OF_ELEMENTS, disabledResult.f1.getValue());
108: 
109:         Assert.assertEquals(disabledResult, enabledResult);
110:     }
