122:                 getDataSet(env).groupBy(0).reduce(new OverwriteObjectsReduce(true)).collect();
123: 
124:         Collections.sort(enabledResult, comparator);
125: 
126:         env.getConfig().disableObjectReuse();
127: 
128:         List<Tuple2<IntValue, IntValue>> disabledResult =
