326:         List<Tuple2<IntValue, IntValue>> enabledResultWithHuge =
327:                 small.crossWithHuge(large).with(new OverwriteObjectsCross()).collect();
328: 
329:         List<Tuple2<IntValue, IntValue>> enabledResultWithTiny =
330:                 small.crossWithTiny(large).with(new OverwriteObjectsCross()).collect();
331: 
332:         Assert.assertThat(enabledResultWithHuge, is(enabledResultWithTiny));
333: 
334:         // test NESTEDLOOP_BLOCKED_OUTER_FIRST and NESTEDLOOP_BLOCKED_OUTER_SECOND with object reuse
335:         // disabled
336: 
337:         env.getConfig().disableObjectReuse();
338: 
339:         List<Tuple2<IntValue, IntValue>> disabledResultWithHuge =
340:                 small.crossWithHuge(large).with(new OverwriteObjectsCross()).collect();
341: 
342:         List<Tuple2<IntValue, IntValue>> disabledResultWithTiny =
343:                 small.crossWithTiny(large).with(new OverwriteObjectsCross()).collect();
344: 
345:         Assert.assertThat(disabledResultWithHuge, is(disabledResultWithTiny));
