368:     private DataStream<Tuple2<IntValue, IntValue>> getDataSet(
369:             ExecutionEnvironment env, int numberOfElements, int keyRange) {
370:         return env.fromCollection(
371:                 new TupleIntValueIntValueIterator(numberOfElements, keyRange),
372:                 TupleTypeInfo.<Tuple2<IntValue, IntValue>>getBasicAndBasicValueTupleTypeInfo(
373:                         IntValue.class, IntValue.class));
374:     }
375: 
376:     private DataStream<Tuple2<IntValue, IntValue>> getDataStream(ExecutionEnvironment env) {
377:         return getDataSet(env, NUMBER_OF_ELEMENTS, KEY_RANGE);
378:     }
