392:     private static class TupleIntValueIntValueIterator
393:             implements Iterator<Tuple2<IntValue, IntValue>>, Serializable {
394:         private int numElements;
395:         private final int keyRange;
396:         private Tuple2<IntValue, IntValue> ret = new Tuple2<>(new IntValue(), new IntValue());
397: 
398:         public TupleIntValueIntValueIterator(int numElements, int keyRange) {
399:             this.numElements = numElements;
400:             this.keyRange = keyRange;
401:         }
402: 
403:         private final Random rnd = new Random(123);
404: 
405:         @Override
406:         public boolean hasNext() {
407:             return numElements > 0;
408:         }
409: 
410:         @Override
411:         public Tuple2<IntValue, IntValue> next() {
412:             numElements--;
413:             ret.f0.setValue(rnd.nextInt(keyRange));
414:             ret.f1.setValue(1);
415:             return ret;
416:         }
