416:     static String runJobAndGetExternalizedCheckpoint(
417:             StateBackend backend,
418:             @Nullable String externalCheckpoint,
419:             MiniClusterWithClientResource cluster,
420:             RecoveryClaimMode recoveryClaimMode,
421:             Configuration jobConfig,
422:             int consecutiveCheckpoints,
423:             boolean retainCheckpoints)
424:             throws Exception {
425:         JobGraph initialJobGraph =
426:                 getJobGraph(
427:                         backend,
428:                         externalCheckpoint,
429:                         recoveryClaimMode,
430:                         jobConfig,
431:                         retainCheckpoints);
432:         NotifyingInfiniteTupleSource.countDownLatch = new CountDownLatch(PARALLELISM);
433:         cluster.getClusterClient().submitJob(initialJobGraph).get();
434: 
435:         // wait until all sources have been started
436:         NotifyingInfiniteTupleSource.countDownLatch.await();
437: 
438:         waitForCheckpoint(
439:                 initialJobGraph.getJobID(), cluster.getMiniCluster(), consecutiveCheckpoints);
440:         cluster.getClusterClient().cancel(initialJobGraph.getJobID()).get();
441:         waitUntilJobCanceled(initialJobGraph.getJobID(), cluster.getClusterClient());
442: 
443:         return getLatestCompletedCheckpointPath(
444:                         initialJobGraph.getJobID(), cluster.getMiniCluster())
445:                 .<IllegalStateException>orElseThrow(
446:                         () -> {
447:                             throw new IllegalStateException("Checkpoint not generated");
448:                         });
449:     }
