459:     /**
460:      * {@code TestingRescaleManagerContext} provides methods for adjusting the elapsed time and for
461:      * adjusting the available resources for rescaling.
462:      */
463:     private static class TestingRescaleManagerContext implements RescaleManager.Context {
464: 
465:         // default configuration values to allow for easy transitioning between the phases
466:         private static final Duration SCALING_MIN = Duration.ofHours(1);
467:         private static final Duration SCALING_MAX = Duration.ofHours(2);
468: 
469:         // configuration that defines what kind of rescaling would be possible
470:         private boolean hasSufficientResources = false;
471:         private boolean hasDesiredResources = false;
472: 
473:         // internal state used for assertions
474:         private final AtomicBoolean rescaleTriggered = new AtomicBoolean();
475:         private final SortedMap<Instant, List<Runnable>> scheduledTasks = new TreeMap<>();
476: 
477:         // Instant.MIN makes debugging easier because timestamps become human-readable
478:         private final Instant initializationTime = Instant.MIN;
479:         private Duration elapsedTime = Duration.ZERO;
480: 
481:         // ///////////////////////////////////////////////
482:         // Context creation
483:         // ///////////////////////////////////////////////
484: 
485:         public static TestingRescaleManagerContext stableContext() {
486:             return new TestingRescaleManagerContext();
487:         }
488: 
489:         private TestingRescaleManagerContext() {
490:             // no rescaling is enabled by default
491:             revertAnyParallelismImprovements();
492:         }
493: 
494:         public void revertAnyParallelismImprovements() {
495:             this.hasSufficientResources = false;
496:             this.hasDesiredResources = false;
497:         }
498: 
499:         public TestingRescaleManagerContext withDesiredRescaling() {
500:             // having desired resources should also mean that the sufficient resources are met
501:             this.hasSufficientResources = true;
502:             this.hasDesiredResources = true;
503: 
504:             return this;
505:         }
506: 
507:         public TestingRescaleManagerContext withSufficientRescaling() {
508:             this.hasSufficientResources = true;
509:             this.hasDesiredResources = false;
510: 
511:             return this;
512:         }
513: 
514:         // ///////////////////////////////////////////////
515:         // RescaleManager.Context interface methods
516:         // ///////////////////////////////////////////////
517: 
518:         @Override
519:         public boolean hasSufficientResources() {
520:             return this.hasSufficientResources;
521:         }
522: 
523:         @Override
524:         public boolean hasDesiredResources() {
525:             return this.hasDesiredResources;
526:         }
527: 
528:         @Override
529:         public void rescale() {
530:             rescaleTriggered.set(true);
531:         }
532: 
533:         @Override
534:         public void scheduleOperation(Runnable callback, Duration delay) {
535:             final Instant triggerTime =
536:                     Objects.requireNonNull(initializationTime).plus(elapsedTime).plus(delay);
537:             if (!scheduledTasks.containsKey(triggerTime)) {
538:                 scheduledTasks.put(triggerTime, new ArrayList<>());
539:             }
540: 
541:             scheduledTasks.get(triggerTime).add(callback);
542:         }
543: 
544:         // ///////////////////////////////////////////////
545:         // Test instance creation
546:         // ///////////////////////////////////////////////
547: 
548:         /**
549:          * Creates the {@code DefaultRescaleManager} test instance and transitions into a period in
550:          * time where the instance is in cooldown phase.
551:          */
552:         public DefaultRescaleManager createTestInstanceInCooldownPhase() {
553:             return createTestInstance(this::transitionIntoCooldownTimeframe);
554:         }
555: 
556:         /**
557:          * Creates the {@code DefaultRescaleManager} test instance and transitions into a period in
558:          * time where the instance is in soft-rescaling phase.
559:          */
560:         public DefaultRescaleManager createTestInstanceInSoftRescalePhase() {
561:             return createTestInstance(this::transitionIntoSoftScalingTimeframe);
562:         }
563: 
564:         /**
565:          * Creates the {@code DefaultRescaleManager} test instance and transitions into a period in
566:          * time where the instance is in hard-rescaling phase.
567:          */
568:         public DefaultRescaleManager createTestInstanceInHardRescalePhase() {
569:             return createTestInstance(this::transitionIntoHardScalingTimeframe);
570:         }
571: 
572:         /**
573:          * Initializes the test instance and sets the context's elapsed time based on the passed
574:          * callback.
575:          */
576:         private DefaultRescaleManager createTestInstance(Runnable timeTransitioning) {
577:             final DefaultRescaleManager testInstance =
578:                     new DefaultRescaleManager(
579:                             initializationTime,
580:                             // clock that returns the time based on the configured elapsedTime
581:                             () -> Objects.requireNonNull(initializationTime).plus(elapsedTime),
582:                             this,
583:                             SCALING_MIN,
584:                             SCALING_MAX,
585:                             Duration.ofHours(5)) {
586:                         @Override
587:                         public void onChange() {
588:                             super.onChange();
589: 
590:                             // hack to avoid calling this method in every test method
591:                             // we want to trigger tasks that are meant to run right-away
592:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
593:                         }
594: 
595:                         @Override
596:                         public void onTrigger() {
597:                             super.onTrigger();
598: 
599:                             // hack to avoid calling this method in every test method
600:                             // we want to trigger tasks that are meant to run right-away
601:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
602:                         }
603:                     };
604: 
605:             timeTransitioning.run();
606:             return testInstance;
607:         }
608: 
609:         // ///////////////////////////////////////////////
610:         // Time-adjustment functionality
611:         // ///////////////////////////////////////////////
612: 
613:         /**
614:          * Transitions the context's time to a moment that falls into the test instance's cooldown
615:          * phase.
616:          */
617:         public void transitionIntoCooldownTimeframe() {
618:             this.elapsedTime = SCALING_MIN.dividedBy(2);
619:             this.triggerOutdatedTasks();
620:         }
621: 
622:         /**
623:          * Transitions the context's time to a moment that falls into the test instance's
624:          * soft-scaling phase.
625:          */
626:         public void transitionIntoSoftScalingTimeframe() {
627:             // the state transition is scheduled based on the current event's time rather than the
628:             // initializationTime
629:             this.elapsedTime = elapsedTime.plus(SCALING_MIN);
630: 
631:             // make sure that we're still below the scalingIntervalMax
632:             this.elapsedTime = elapsedTime.plus(SCALING_MAX.minus(elapsedTime).dividedBy(2));
633:             this.triggerOutdatedTasks();
634:         }
635: 
636:         /**
637:          * Transitions the context's time to a moment that falls into the test instance's
638:          * hard-scaling phase.
639:          */
640:         public void transitionIntoHardScalingTimeframe() {
641:             // the state transition is scheduled based on the current event's time rather than the
642:             // initializationTime
643:             this.elapsedTime = elapsedTime.plus(SCALING_MAX).plusMinutes(1);
644:             this.triggerOutdatedTasks();
645:         }
646: 
647:         private void triggerOutdatedTasks() {
648:             while (!scheduledTasks.isEmpty()) {
649:                 final Instant timeOfExecution = scheduledTasks.firstKey();
650:                 if (!timeOfExecution.isAfter(
651:                         Objects.requireNonNull(initializationTime).plus(elapsedTime))) {
652:                     scheduledTasks.remove(timeOfExecution).forEach(Runnable::run);
653:                 } else {
654:                     break;
655:                 }
656:             }
657:         }
658: 
659:         // ///////////////////////////////////////////////
660:         // Methods for verifying the context's state
661:         // ///////////////////////////////////////////////
662: 
663:         public boolean rescaleWasTriggered() {
664:             return rescaleTriggered.get();
665:         }
666: 
667:         public int numberOfTasksWaiting() {
668:             return scheduledTasks.size();
669:         }
670: 
671:         public boolean additionalTasksWaiting() {
672:             return !scheduledTasks.isEmpty();
673:         }
674:     }
675: }
