46: /** Array {@link ColumnReader}. TODO Currently ARRAY type only support non nested case. */
47: public class ArrayColumnReader extends BaseVectorizedColumnReader {
48: 
49:     // The value read in last time
50:     private Object lastValue;
51: 
52:     // flag to indicate if there is no data in parquet data page
53:     private boolean eof = false;
54: 
55:     // flag to indicate if it's the first time to read parquet data page with this instance
56:     boolean isFirstRow = true;
57: 
58:     public ArrayColumnReader(
59:             ColumnDescriptor descriptor,
60:             PageReader pageReader,
61:             boolean isUtcTimestamp,
62:             Type elementType,
63:             LogicalType logicalType)
64:             throws IOException {
65:         super(descriptor, pageReader, isUtcTimestamp, elementType, logicalType);
66:     }
67: 
68:     @Override
69:     public void readToVector(int readNumber, WritableColumnVector vector) {
70:         HeapArrayVector lcv = (HeapArrayVector) vector;
71:         // before readBatch, initial the size of offsets & lengths as the default value,
72:         // the actual size will be assigned in setChildrenInfo() after reading complete.
73:         lcv.setOffsets(new long[VectorizedColumnBatch.DEFAULT_SIZE]);
74:         lcv.setLengths(new long[VectorizedColumnBatch.DEFAULT_SIZE]);
75: 
76:         LogicalType elementType = ((ArrayType) logicalType).getElementType();
77: 
78:         // read the first row in parquet data page, this will be only happened once for this
79:         // instance
80:         if (isFirstRow) {
81:             if (!fetchNextValue(elementType)) {
82:                 return;
83:             }
84:             isFirstRow = false;
85:         }
86: 
87:         // Because the length of ListColumnVector.child can't be known now,
88:         // the valueList will save all data for ListColumnVector temporary.
89:         List<Object> valueList = new ArrayList<>();
90: 
91:         int index = collectDataFromParquetPage(readNumber, lcv, valueList, elementType);
92:         // Convert valueList to array for the ListColumnVector.child
93:         fillColumnVector(elementType, lcv, valueList, index);
94:     }
95: 
96:     /**
97:      * Reads a single value from parquet page, puts it into lastValue. Returns a boolean indicating
98:      * if there is more values to read (true).
99:      *
100:      * @param elementType the element type of array
101:      * @return boolean
102:      */
103:     private boolean fetchNextValue(LogicalType elementType) {
104:         int left = readPageIfNeed();
105:         if (left > 0) {
106:             // get the values of repetition and definitionLevel
107:             readRepetitionAndDefinitionLevels();
108:             // read the data if it isn't null
109:             if (definitionLevel == maxDefLevel) {
110:                 if (isCurrentPageDictionaryEncoded) {
111:                     lastValue = dataColumn.readValueDictionaryId();
112:                 } else {
113:                     lastValue = readPrimitiveTypedRow(elementType);
114:                 }
115:             } else {
116:                 lastValue = null;
117:             }
118:             return true;
119:         } else {
120:             eof = true;
121:             return false;
122:         }
123:     }
124: 
125:     private int readPageIfNeed() {
126:         // Compute the number of values we want to read in this page.
127:         int leftInPage = (int) (endOfPageValueCount - valuesRead);
128:         if (leftInPage == 0) {
129:             // no data left in current page, load data from new page
130:             readPage();
131:             leftInPage = (int) (endOfPageValueCount - valuesRead);
132:         }
133:         return leftInPage;
134:     }
135: 
136:     // Need to be in consistent with that VectorizedPrimitiveColumnReader#readBatchHelper
137:     // TODO Reduce the duplicated code
138:     private Object readPrimitiveTypedRow(LogicalType category) {
139:         switch (category.getTypeRoot()) {
140:             case CHAR:
141:             case VARCHAR:
142:             case BINARY:
143:             case VARBINARY:
144:                 return dataColumn.readBytes();
145:             case BOOLEAN:
146:                 return dataColumn.readBoolean();
147:             case TIME_WITHOUT_TIME_ZONE:
148:             case DATE:
149:             case INTEGER:
150:                 return dataColumn.readInteger();
151:             case TINYINT:
152:                 return dataColumn.readTinyInt();
153:             case SMALLINT:
154:                 return dataColumn.readSmallInt();
155:             case BIGINT:
156:                 return dataColumn.readLong();
157:             case FLOAT:
158:                 return dataColumn.readFloat();
159:             case DOUBLE:
160:                 return dataColumn.readDouble();
161:             case DECIMAL:
162:                 switch (descriptor.getPrimitiveType().getPrimitiveTypeName()) {
163:                     case INT32:
164:                         return dataColumn.readInteger();
165:                     case INT64:
166:                         return dataColumn.readLong();
167:                     case BINARY:
168:                     case FIXED_LEN_BYTE_ARRAY:
169:                         return dataColumn.readBytes();
170:                 }
171:             case TIMESTAMP_WITHOUT_TIME_ZONE:
172:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
173:                 return dataColumn.readTimestamp();
174:             default:
175:                 throw new RuntimeException("Unsupported type in the list: " + category);
176:         }
177:     }
178: 
179:     private Object dictionaryDecodeValue(LogicalType elementType, Integer dictionaryValue) {
180:         if (dictionaryValue == null) {
181:             return null;
182:         }
183: 
184:         switch (elementType.getTypeRoot()) {
185:             case CHAR:
186:             case VARCHAR:
187:             case BINARY:
188:             case VARBINARY:
189:                 return dictionary.readBytes(dictionaryValue);
190:             case DATE:
191:             case TIME_WITHOUT_TIME_ZONE:
192:             case INTEGER:
193:                 return dictionary.readInteger(dictionaryValue);
194:             case BOOLEAN:
195:                 return dictionary.readBoolean(dictionaryValue) ? 1 : 0;
196:             case DOUBLE:
197:                 return dictionary.readDouble(dictionaryValue);
198:             case FLOAT:
199:                 return dictionary.readFloat(dictionaryValue);
200:             case TINYINT:
201:                 return dictionary.readTinyInt(dictionaryValue);
202:             case SMALLINT:
203:                 return dictionary.readSmallInt(dictionaryValue);
204:             case BIGINT:
205:                 return dictionary.readLong(dictionaryValue);
206:             case DECIMAL:
207:                 switch (descriptor.getPrimitiveType().getPrimitiveTypeName()) {
208:                     case INT32:
209:                         return dictionary.readInteger(dictionaryValue);
210:                     case INT64:
211:                         return dictionary.readLong(dictionaryValue);
212:                     case FIXED_LEN_BYTE_ARRAY:
213:                     case BINARY:
214:                         return dictionary.readBytes(dictionaryValue);
215:                 }
216:             case TIMESTAMP_WITHOUT_TIME_ZONE:
217:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
218:                 return dictionary.readTimestamp(dictionaryValue);
219:             default:
220:                 throw new RuntimeException("Unsupported type in the list: " + elementType);
221:         }
222:     }
