293:     private void fillColumnVector(
294:             LogicalType type, HeapArrayVector lcv, List valueList, int elementNum) {
295:         int total = valueList.size();
296:         setChildrenInfo(lcv, total, elementNum);
297:         switch (type.getTypeRoot()) {
298:             case CHAR:
299:             case VARCHAR:
300:             case BINARY:
301:             case VARBINARY:
302:                 HeapBytesVector bytesVector = new HeapBytesVector(total);
303:                 bytesVector.reset();
304:                 lcv.setChild(bytesVector);
305:                 for (int i = 0; i < valueList.size(); i++) {
306:                     byte[] src = (byte[]) valueList.get(i);
307:                     if (src == null) {
308:                         ((HeapBytesVector) lcv.getChild()).setNullAt(i);
309:                     } else {
310:                         ((HeapBytesVector) lcv.getChild()).appendBytes(i, src, 0, src.length);
311:                     }
312:                 }
313:                 break;
314:             case BOOLEAN:
315:                 HeapBooleanVector booleanVector = new HeapBooleanVector(total);
316:                 booleanVector.reset();
317:                 lcv.setChild(booleanVector);
318:                 for (int i = 0; i < valueList.size(); i++) {
319:                     if (valueList.get(i) == null) {
320:                         ((HeapBooleanVector) lcv.getChild()).setNullAt(i);
321:                     } else {
322:                         ((HeapBooleanVector) lcv.getChild()).vector[i] = (boolean) valueList.get(i);
323:                     }
324:                 }
325:                 break;
326:             case TINYINT:
327:                 HeapByteVector byteVector = new HeapByteVector(total);
328:                 byteVector.reset();
329:                 lcv.setChild(byteVector);
330:                 for (int i = 0; i < valueList.size(); i++) {
331:                     if (valueList.get(i) == null) {
332:                         ((HeapByteVector) lcv.getChild()).setNullAt(i);
333:                     } else {
334:                         ((HeapByteVector) lcv.getChild()).vector[i] =
335:                                 ((List<Integer>) valueList).get(i).byteValue();
336:                     }
337:                 }
338:                 break;
339:             case SMALLINT:
340:                 HeapShortVector shortVector = new HeapShortVector(total);
341:                 shortVector.reset();
342:                 lcv.setChild(shortVector);
343:                 for (int i = 0; i < valueList.size(); i++) {
344:                     if (valueList.get(i) == null) {
345:                         ((HeapShortVector) lcv.getChild()).setNullAt(i);
346:                     } else {
347:                         ((HeapShortVector) lcv.getChild()).vector[i] =
348:                                 ((List<Integer>) valueList).get(i).shortValue();
349:                     }
350:                 }
351:                 break;
352:             case INTEGER:
353:             case DATE:
354:             case TIME_WITHOUT_TIME_ZONE:
355:                 HeapIntVector intVector = new HeapIntVector(total);
356:                 intVector.reset();
357:                 lcv.setChild(intVector);
358:                 for (int i = 0; i < valueList.size(); i++) {
359:                     if (valueList.get(i) == null) {
360:                         ((HeapIntVector) lcv.getChild()).setNullAt(i);
361:                     } else {
362:                         ((HeapIntVector) lcv.getChild()).vector[i] =
363:                                 ((List<Integer>) valueList).get(i);
364:                     }
365:                 }
366:                 break;
367:             case FLOAT:
368:                 HeapFloatVector floatVector = new HeapFloatVector(total);
369:                 floatVector.reset();
370:                 lcv.setChild(floatVector);
371:                 for (int i = 0; i < valueList.size(); i++) {
372:                     if (valueList.get(i) == null) {
373:                         ((HeapFloatVector) lcv.getChild()).setNullAt(i);
374:                     } else {
375:                         ((HeapFloatVector) lcv.getChild()).vector[i] =
376:                                 ((List<Float>) valueList).get(i);
377:                     }
378:                 }
379:                 break;
380:             case BIGINT:
381:                 HeapLongVector longVector = new HeapLongVector(total);
382:                 longVector.reset();
383:                 lcv.setChild(longVector);
384:                 for (int i = 0; i < valueList.size(); i++) {
385:                     if (valueList.get(i) == null) {
386:                         ((HeapLongVector) lcv.getChild()).setNullAt(i);
387:                     } else {
388:                         ((HeapLongVector) lcv.getChild()).vector[i] =
389:                                 ((List<Long>) valueList).get(i);
390:                     }
391:                 }
392:                 break;
393:             case DOUBLE:
394:                 HeapDoubleVector doubleVector = new HeapDoubleVector(total);
395:                 doubleVector.reset();
396:                 lcv.setChild(doubleVector);
397:                 for (int i = 0; i < valueList.size(); i++) {
398:                     if (valueList.get(i) == null) {
399:                         ((HeapDoubleVector) lcv.getChild()).setNullAt(i);
400:                     } else {
401:                         ((HeapDoubleVector) lcv.getChild()).vector[i] =
402:                                 ((List<Double>) valueList).get(i);
403:                     }
404:                 }
405:                 break;
406:             case TIMESTAMP_WITHOUT_TIME_ZONE:
407:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
408:                 HeapTimestampVector timestampVector = new HeapTimestampVector(total);
409:                 timestampVector.reset();
410:                 lcv.setChild(timestampVector);
411:                 for (int i = 0; i < valueList.size(); i++) {
412:                     if (valueList.get(i) == null) {
413:                         ((HeapTimestampVector) lcv.getChild()).setNullAt(i);
414:                     } else {
415:                         ((HeapTimestampVector) lcv.getChild())
