471:                                 ((HeapBytesVector)
472:                                                 ((ParquetDecimalVector) lcv.getChild()).getVector())
473:                                         .appendBytes(i, src, 0, src.length);
474:                             }
475:                         }
476:                         break;
477:                 }
478:                 break;
