209:             boolean override,
210:             boolean partition,
211:             boolean dynamicGrouped,
212:             LinkedHashMap<String, String> staticPartitions,
213:             AtomicReference<FileSystemOutputFormat<Row>> sinkRef)
214:             throws Exception {
215:         String[] columnNames = new String[] {"a", "b", "c"};
216:         String[] partitionColumns = partition ? new String[] {"c"} : new String[0];
217: 
218:         TableMetaStoreFactory msFactory =
219:                 new FileSystemCommitterTest.TestMetaStoreFactory(new Path(outputPath.toString()));
220:         FileSystemOutputFormat<Row> sink =
