233:         sinkRef.set(sink);
234: 
235:         return new OneInputStreamOperatorTestHarness<>(
236:                 new StreamSink<>(new OutputFormatSinkFunction<>(sink)),
237:                 // test parallelism
238:                 3,
239:                 3,
240:                 0);
241:     }
